// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const validator = require('validator');

const app = express();

// ============================================
// MIDDLEWARE: Security & Validation
// ============================================

// 1. Helmet - Set security HTTP headers
app.use(helmet());

// 2. CORS - Configure Cross-Origin Resource Sharing
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. Body Parser - Limit request payload size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data Sanitization
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss()); // Prevent XSS attacks

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: false,
});

// ============================================
// LOGGING
// ============================================

const logger = {
  info: (message, data = {}) => {
    console.log(JSON.stringify({ level: 'info', timestamp: new Date().toISOString(), message, ...data }));
  },
  error: (message, error, data = {}) => {
    console.error(JSON.stringify({ level: 'error', timestamp: new Date().toISOString(), message, error: error?.message, ...data }));
  },
  warn: (message, data = {}) => {
    console.warn(JSON.stringify({ level: 'warn', timestamp: new Date().toISOString(), message, ...data }));
  },
};

// ============================================
// VALIDATION UTILITIES
// ============================================

const validatePagination = (page, limit) => {
  const errors = [];

  if (page) {
    const pageNum = parseInt(page, 10);
    if (isNaN(pageNum) || pageNum < 1) {
      errors.push('Page must be a positive integer');
    }
  }

  if (limit) {
    const limitNum = parseInt(limit, 10);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      errors.push('Limit must be between 1 and 100');
    }
  }

  return errors;
};

const sanitizeUserOutput = (user) => {
  // Return only safe user fields
  return {
    id: user.id,
    name: validator.trim(user.name),
    // Don't return sensitive fields like passwords, tokens, etc.
  };
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error('Health check failed', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get users with validation
app.get('/api/users', limiter, (req, res) => {
  try {
    // Input validation
    const { page = 1, limit = 10 } = req.query;
    const validationErrors = validatePagination(page, limit);

    if (validationErrors.length > 0) {
      logger.warn('Invalid pagination parameters', { page, limit, errors: validationErrors });
      return res.status(400).json({
        error: 'Invalid input',
        details: validationErrors,
      });
    }

    const pageNum = Math.max(1, parseInt(page, 10));
    const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10)));

    // Mock user data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', password: 'secret' },
      { id: 2, name: 'Bob', email: 'bob@example.com', password: 'secret' },
    ];

    // Implement pagination
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = startIndex + limitNum;
    const paginatedUsers = mockUsers.slice(startIndex, endIndex);

    // Sanitize output - remove sensitive fields
    const sanitizedUsers = paginatedUsers.map(sanitizeUserOutput);

    res.status(200).json({
      success: true,
      data: sanitizedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: mockUsers.length,
        totalPages: Math.ceil(mockUsers.length / limitNum),
      },
    });

    logger.info('Users retrieved', { page: pageNum, limit: limitNum, count: sanitizedUsers.length });
  } catch (error) {
    logger.error('Error retrieving users', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// Get specific user with validation
app.get('/api/users/:id', limiter, (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID - must be numeric
    if (!validator.isNumeric(id)) {
      logger.warn('Invalid user ID format', { id });
      return res.status(400).json({
        error: 'Invalid input',
        details: ['User ID must be numeric'],
      });
    }

    const userId = parseInt(id, 10);

    // Mock user data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', password: 'secret' },
      { id: 2, name: 'Bob', email: 'bob@example.com', password: 'secret' },
    ];

    const user = mockUsers.find(u => u.id === userId);

    if (!user) {
      logger.warn('User not found', { userId });
      return res.status(404).json({
        error: 'Not found',
        details: ['User does not exist'],
      });
    }

    res.status(200).json({
      success: true,
      data: sanitizeUserOutput(user),
    });

    logger.info('User retrieved', { userId });
  } catch (error) {
    logger.error('Error retrieving user', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  logger.warn('Not found', { method: req.method, path: req.path });
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource does not exist',
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const message = err.message || 'Internal server error';

  logger.error('Unhandled error', err, {
    method: req.method,
    path: req.path,
    status,
  });

  res.status(status).json({
    error: message,
    message: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
const requiredEnvVars = [];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  logger.error('Missing required environment variables', new Error('Env validation failed'), { missing: missingEnvVars });
  process.exit(1);
}

const server = app.listen(PORT, () => {
  logger.info('Server started', {
    port: PORT,
    environment: NODE_ENV,
    nodeVersion: process.version,
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled rejection', reason, { promise });
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught exception', error);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js - Comprehensive Recommendations

## Executive Summary
The current app.js lacks critical security controls including input validation, error handling, rate limiting, and security headers. This document outlines vulnerabilities and improvements.

---

## 🔴 CRITICAL VULNERABILITIES

### 1. **No Input Validation**
**Risk**: NoSQL Injection, XSS, Type Errors
```javascript
// ❌ BEFORE - No validation
app.get('/users', (req, res) => {
  res.json(users);
});

// ✅ AFTER - With validation
const validatePagination = (page, limit) => {
  const errors = [];
  if (page && (isNaN(parseInt(page, 10)) || parseInt(page, 10) < 1)) {
    errors.push('Page must be a positive integer');
  }
  return errors;
};
```

### 2. **Exposed Sensitive Data**
**Risk**: Information Disclosure
```javascript
// ❌ BEFORE - Returns passwords and sensitive fields
{ id: 1, name: 'Alice', email: 'alice@example.com', password: 'secret' }

// ✅ AFTER - Sanitized output
const sanitizeUserOutput = (user) => ({
  id: user.id,
  name: user.name,
  // Explicitly exclude: password, tokens, internal fields
});
```

### 3. **No Security Headers**
**Risk**: Clickjacking, XSS, MIME Sniffing
```javascript
// ✅ AFTER - Add Helmet middleware
const helmet = require('helmet');
app.use(helmet());
```

### 4. **No Rate Limiting**
**Risk**: Denial of Service (DoS)
```javascript
// ✅ AFTER - Add rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use('/api/', limiter);
```

---

## 🟠 HIGH PRIORITY ISSUES

### 5. **Missing Error Handling**
**Risk**: Information Disclosure, Unstable Service
```javascript
// ❌ BEFORE - No try-catch
app.get('/users', (req, res) => {
  res.json(users);
});

// ✅ AFTER - With error handling
app.get('/api/users', (req, res) => {
  try {
    // ... business logic
  } catch (error) {
    logger.error('Error retrieving users', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

### 6. **No CORS Protection**
**Risk**: Cross-Origin Attacks
```javascript
// ✅ AFTER - Configure CORS
const cors = require('cors');
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
}));
```

### 7. **No Request Size Limits**
**Risk**: Large Payload/Memory Exhaustion Attacks
```javascript
// ✅ AFTER - Limit body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

### 8. **No Input Sanitization**
**Risk**: NoSQL Injection, XSS
```javascript
// ✅ AFTER - Add sanitization middleware
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
app.use(mongoSanitize());
app.use(xss());
```

---

## 🟡 MEDIUM PRIORITY ISSUES

### 9. **Weak Logging**
**Risk**: Cannot track security incidents
```javascript
// ❌ BEFORE
console.log('Server running on port 3000');

// ✅ AFTER - Structured logging
const logger = {
  info: (message, data = {}) => {
    console.log(JSON.stringify({
      level: 'info',
      timestamp: new Date().toISOString(),
      message,
      ...data
    }));
  },
  error: (message, error, data = {}) => {
    console.error(JSON.stringify({
      level: 'error',
      timestamp: new Date().toISOString(),
      message,
      error: error?.message,
      ...data
    }));
  },
};
```

### 10. **No Environment Validation**
**Risk**: Misconfiguration, Missing Critical Settings
```javascript
// ✅ AFTER - Validate env variables
const requiredEnvVars = [];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);
if (missingEnvVars.length > 0) {
  logger.error('Missing env variables', new Error('Env validation failed'));
  process.exit(1);
}
```

### 11. **No Unhandled Exception Handling**
**Risk**: Process Crash, Service Unavailability
```javascript
// ✅ AFTER - Global error handlers
process.on('unhandledRejection', (reason) => {
  logger.error('Unhandled rejection', reason);
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught exception', error);
  process.exit(1);
});
```

### 12. **No Type Validation**
**Risk**: Type Coercion Attacks
```javascript
// ✅ AFTER - Validate parameter types
if (!validator.isNumeric(id)) {
  return res.status(400).json({
    error: 'Invalid input',
    details: ['User ID must be numeric'],
  });
}
```

---

## 📋 SECURITY CHECKLIST

- [ ] Add Helmet for security headers
- [ ] Implement rate limiting (express-rate-limit)
- [ ] Add CORS configuration
- [ ] Implement input validation (validator.js)
- [ ] Add request size limits
