        .get('/api/users/1')
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.data.id).toBe(1);
      expect(response.body.data.name).toBeDefined();
    });
  });

  // ============================================
  // CORS TESTS
  // ============================================

  describe('CORS', () => {
    test('should set appropriate CORS headers', async () => {
      const response = await request(app)
        .options('/api/users')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });
  });
});

# Migration Guide: Securing Your Express App

## Overview
This guide helps you migrate from the basic `app.js` to the security-hardened `app_improved.js`.

---

## Step-by-Step Migration

### Step 1: Install Dependencies
```bash
npm install helmet express-rate-limit cors validator express-mongo-sanitize xss-clean
```

### Step 2: Update Environment Configuration
Create a `.env` file:
```env
NODE_ENV=development
PORT=3000
CORS_ORIGIN=http://localhost:3000
```

For production (`.env.production`):
```env
NODE_ENV=production
PORT=3000
CORS_ORIGIN=https://yourdomain.com
```

### Step 3: Replace app.js
Option A: Directly use `app_improved.js`
```bash
mv app.js app.old.js
mv app_improved.js app.js
npm start
```

Option B: Incrementally add security middleware
```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Step 1: Add Helmet
app.use(helmet());

// Step 2: Add CORS
app.use(cors());

// Step 3: Add body limits
app.use(express.json({ limit: '10kb' }));

// Step 4: Add rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use('/api/', limiter);

// ... rest of your routes
```

### Step 4: Add Input Validation
Update route handlers:
```javascript
// BEFORE
app.get('/users/:id', (req, res) => {
  const user = findUser(req.params.id);
  res.json(user);
});

// AFTER
app.get('/api/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate input
    if (!validator.isNumeric(id)) {
      return res.status(400).json({
        error: 'Invalid input',
        details: ['User ID must be numeric'],
      });
    }

    const user = findUser(parseInt(id, 10));

    if (!user) {
      return res.status(404).json({
        error: 'Not found',
        details: ['User does not exist'],
      });
    }

    res.json({ success: true, data: sanitizeUserOutput(user) });
  } catch (error) {
    logger.error('Error retrieving user', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

### Step 5: Implement Logging
```javascript
const logger = {
  info: (message, data = {}) => {
    console.log(JSON.stringify({
      level: 'info',
      timestamp: new Date().toISOString(),
      message,
      ...data
    }));
  },
  error: (message, error, data = {}) => {
    console.error(JSON.stringify({
      level: 'error',
      timestamp: new Date().toISOString(),
      message,
      error: error?.message,
      ...data
    }));
  },
};
```

### Step 6: Add Global Error Handlers
```javascript
// 404 handler
app.use((req, res) => {
  logger.warn('Not found', { method: req.method, path: req.path });
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error', err);
  res.status(500).json({ error: 'Internal server error' });
});

// Process error handlers
process.on('unhandledRejection', (reason) => {
  logger.error('Unhandled rejection', reason);
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught exception', error);
  process.exit(1);
});
```

### Step 7: Add Data Sanitization
```javascript
const sanitizeUserOutput = (user) => ({
  id: user.id,
  name: validator.trim(user.name),
  // Explicitly exclude sensitive fields:
  // - password
  // - token
  // - apiKey
  // - internalIds
});
```

