// Improved application with security best practices
// Error handling, input validation, and security headers implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================
// MIDDLEWARE: Security & Protection
// ============================================

// Security headers
app.use(helmet());

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'localhost',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// Rate limiting - general
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Rate limiting - strict for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  skipSuccessfulRequests: false,
  message: 'Too many requests, please try again later.'
});

app.use(generalLimiter);

// Body parsing with size limits
app.use(express.json({ 
  limit: '10kb',
  strict: true // Only parse arrays and objects
}));
app.use(express.urlencoded({ 
  limit: '10kb', 
  extended: true 
}));

// Data sanitization against NoSQL injection
app.use(mongoSanitize({
  replaceWith: '_',
  onSanitize: ({ req, key }) => {
    console.warn(`Sanitized key: ${key}`);
  }
}));

// ============================================
// ROUTES
// ============================================

/**
 * GET /api/v1/health
 * Health check endpoint (with dependency checks)
 */
app.get('/api/v1/health', (req, res) => {
  try {
    const health = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      // In production, check actual dependencies
      dependencies: {
        database: process.env.DB_STATUS || 'not configured',
        cache: process.env.CACHE_STATUS || 'not configured'
      }
    };
    res.status(200).json(health);
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * GET /api/v1/users
 * Get list of users with optional filtering
 * Query parameters:
 *   - limit: number of results (1-100, default 10)
 *   - offset: pagination offset (default 0)
 */
app.get(
  '/api/v1/users',
  strictLimiter, // Stricter rate limit for sensitive data
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  // Handle validation errors
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }
    next();
  },
  // Route handler
  (req, res) => {
    try {
      // Get validated query parameters
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = parseInt(req.query.offset) || 0;

      // Mock user data (in production, fetch from database)
      const allUsers = [
        { id: 1, name: 'Alice' }, // Note: Email removed for security
        { id: 2, name: 'Bob' }
      ];

      // Apply pagination
      const paginatedUsers = allUsers.slice(offset, offset + limit);

      // Return paginated results with metadata
      res.status(200).json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length
        }
      });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

/**
 * GET /api/v1/users/:id
 * Get a specific user by ID
 * Security: This endpoint should require authentication
 */
app.get(
  '/api/v1/users/:id',
  strictLimiter,
  // Validate ID parameter
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }
    next();
  },
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Validate ID
      if (isNaN(userId) || userId < 1) {
        return res.status(400).json({ 
          error: 'Invalid user ID' 
        });
      }

      // Mock user lookup
      const user = { id: userId, name: 'User' };

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found' 
        });
      }

      res.status(200).json({ data: user });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

/**
 * Global error handler (must be last)
 * Catches all errors from routes and middleware
 */
app.use((err, req, res, next) => {
  // Log error
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
    url: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: {
      message: NODE_ENV === 'production' 
        ? 'Internal server error' 
        : err.message,
      code: err.code || 'INTERNAL_ERROR'
    }
  };

  // Include request ID for debugging (if available)
  if (req.id) {
    errorResponse.requestId = req.id;
  }

  // Send response
  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

// Example security and validation tests for the improved app
// Run with: jest or npm test

const request = require('supertest');
const app = require('./app_improved');

describe('Security & Input Validation Tests', () => {

  // ========================================
  // HEALTH CHECK TESTS
  // ========================================

  describe('GET /api/v1/health', () => {
    test('Should return health status with 200', async () => {
      const res = await request(app)
        .get('/api/v1/health');

      expect(res.statusCode).toBe(200);
      expect(res.body).toHaveProperty('status', 'ok');
      expect(res.body).toHaveProperty('timestamp');
      expect(res.body).toHaveProperty('uptime');
    });

    test('Should include dependencies info', async () => {
      const res = await request(app)
        .get('/api/v1/health');

      expect(res.body.dependencies).toBeDefined();
    });
  });

  // ========================================
  // INPUT VALIDATION TESTS
  // ========================================

  describe('GET /api/v1/users - Input Validation', () => {

    test('Should accept valid limit parameter', async () => {
      const res = await request(app)
        .get('/api/v1/users')
        .query({ limit: 10, offset: 0 });

      expect(res.statusCode).toBe(200);
      expect(res.body.pagination.limit).toBe(10);
    });

    test('Should reject limit > 100', async () => {
      const res = await request(app)
        .get('/api/v1/users')
        .query({ limit: 150 });

      expect(res.statusCode).toBe(400);
      expect(res.body.error).toBe('Validation failed');
    });

    test('Should reject negative limit', async () => {
      const res = await request(app)
        .get('/api/v1/users')
        .query({ limit: -5 });

      expect(res.statusCode).toBe(400);
    });

    test('Should reject negative offset', async () => {
      const res = await request(app)
        .get('/api/v1/users')
        .query({ offset: -10 });

      expect(res.statusCode).toBe(400);
    });

    test('Should reject non-numeric limit', async () => {
      const res = await request(app)
        .get('/api/v1/users')
        .query({ limit: 'abc' });

      expect(res.statusCode).toBe(400);
    });

    test('Should reject string injection attempts', async () => {
      const res = await request(app)
        .get('/api/v1/users')
        .query({ limit: '10; DROP TABLE users;' });

      expect(res.statusCode).toBe(400);
    });

    test('Should handle NoSQL injection attempts', async () => {
      const res = await request(app)
        .get('/api/v1/users')
        .query({ id: { $gt: 0 } });

      // Should either reject or sanitize
      expect([200, 400]).toContain(res.statusCode);
    });
  });

  // ========================================
  // SECURITY HEADER TESTS
  // ========================================

  describe('Security Headers', () => {

    test('Should include Content-Security-Policy header', async () => {
      const res = await request(app)
        .get('/api/v1/health');

      expect(res.headers['content-security-policy']).toBeDefined();
    });

    test('Should include X-Content-Type-Options header', async () => {
      const res = await request(app)
        .get('/api/v1/health');

