// Improved application with security best practices
// Enhanced error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const { v4: uuidv4 } = require('uuid');
const logger = require('./logger'); // Assume logger module exists

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Set HTTP security headers
app.use(helmet());

// 2. CORS - Configure cross-origin resource sharing
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
    res.setHeader('Access-Control-Max-Age', '3600');
  }

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// 3. Request size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 4. Data sanitization - Prevent NoSQL injection
app.use(mongoSanitize({
  replaceWith: '_',
  onSanitize: ({ req, key }) => {
    logger.warn(`Sanitized suspicious data in ${key}`, { 
      requestId: req.id,
      path: req.path 
    });
  },
}));

// 5. Rate limiting - Prevent brute force attacks
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,
  skip: (req) => {
    // Skip rate limiting for health check
    return req.path === '/health';
  },
  onLimitReached: (req, res, opts) => {
    logger.warn('Rate limit exceeded', {
      ip: req.ip,
      path: req.path,
      requestId: req.id,
    });
  },
});

app.use(globalLimiter);

// Stricter rate limit for sensitive endpoints
const sensitiveEndpointLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 10,
  message: 'Too many attempts, please try again later.',
});

// ============================================================================
// REQUEST LOGGING & TRACKING
// ============================================================================

// Add unique request ID and logging
app.use((req, res, next) => {
  req.id = uuidv4();

  // Log request
  logger.info(`${req.method} ${req.path}`, {
    requestId: req.id,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  // Log response
  res.on('finish', () => {
    logger.info(`Response ${res.statusCode}`, {
      requestId: req.id,
      statusCode: res.statusCode,
      duration: `${Date.now() - req.startTime}ms`,
    });
  });

  req.startTime = Date.now();
  next();
});

// ============================================================================
// ERROR HANDLING UTILITIES
// ============================================================================

// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Input validation helper
const validateQueryParams = (allowedParams, queryParams) => {
  const errors = {};

  // Check for unexpected parameters
  Object.keys(queryParams).forEach((key) => {
    if (!allowedParams.includes(key)) {
      errors[key] = `Unexpected parameter: ${key}`;
    }
  });

  return Object.keys(errors).length > 0 ? errors : null;
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health Check Endpoint
 * Purpose: Service monitoring
 * Security: Minimal data exposed
 */
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
    });
  } catch (error) {
    logger.error('Health check failed', {
      requestId: req.id,
      error: error.message,
    });
    next(error);
  }
});

/**
 * Get Users Endpoint
 * Purpose: Retrieve list of users with optional filtering
 * Security: Input validation, rate limiting, output sanitization
 */
app.get('/users', sensitiveEndpointLimiter, (req, res, next) => {
  try {
    // 1. VALIDATE INPUT
    const allowedParams = ['limit', 'offset', 'role'];
    const validationErrors = validateQueryParams(allowedParams, req.query);

    if (validationErrors) {
      logger.warn('Invalid query parameters', {
        requestId: req.id,
        errors: validationErrors,
      });
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: validationErrors,
      });
    }

    // 2. PARSE AND VALIDATE LIMIT
    let limit = parseInt(req.query.limit, 10) || 10;
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be an integer between 1 and 100',
      });
    }

    // 3. PARSE AND VALIDATE OFFSET
    let offset = parseInt(req.query.offset, 10) || 0;
    if (!Number.isInteger(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a non-negative integer',
      });
    }

    // 4. VALIDATE ROLE FILTER (if provided)
    const allowedRoles = ['user', 'admin', 'moderator'];
    if (req.query.role && !allowedRoles.includes(req.query.role)) {
      return res.status(400).json({
        error: 'Invalid role parameter',
        message: `Role must be one of: ${allowedRoles.join(', ')}`,
      });
    }

    // 5. MOCK DATA (In production, query from database with parameterized queries)
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    // 6. FILTER DATA
    let filteredUsers = mockUsers;
    if (req.query.role) {
      filteredUsers = mockUsers.filter(u => u.role === req.query.role);
    }

    // 7. APPLY PAGINATION
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    // 8. SANITIZE OUTPUT - Remove sensitive fields
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: validator.escape(user.email), // Escape for HTML context
      role: user.role,
    }));

    // 9. RETURN RESPONSE WITH METADATA
    res.status(200).json({
      data: sanitizedUsers,
      pagination: {
        offset,
        limit,
        total: filteredUsers.length,
      },
      requestId: req.id,
    });

  } catch (error) {
    logger.error('Error fetching users', {
      requestId: req.id,
      error: error.message,
      stack: error.stack,
    });
    next(error);
  }
});

/**
 * Catch-all 404 handler
 */
app.use((req, res) => {
  logger.warn('Route not found', {
    requestId: req.id,
    method: req.method,
    path: req.path,
  });
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested endpoint does not exist',
    requestId: req.id,
  });
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Global error handler (must be last)
 * Catches all errors and formats response
 */
app.use((err, req, res, next) => {
  const requestId = req.id || uuidv4();

  // Determine status code
  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log error
  logger.error('Unhandled error', {
    requestId,
    statusCode,
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  // Prepare response
  const response = {
    error: err.message || 'Internal Server Error',
    statusCode,
    requestId,
  };

  // Include stack trace only in development
  if (isDevelopment) {
    response.stack = err.stack;
  }

  // Send response
  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running`, {
    port: PORT,
    host: HOST,
    environment: process.env.NODE_ENV || 'development',
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

// Simple logger module for application logging
// In production, use winston, bunyan, or similar

const fs = require('fs');
const path = require('path');

const logDir = './logs';
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir);
}

const getTimestamp = () => new Date().toISOString();

const log = (level, message, metadata = {}) => {
  const logEntry = {
    timestamp: getTimestamp(),
    level,
    message,
    ...metadata,
  };

  const logMessage = JSON.stringify(logEntry);

  // Log to console in development
  if (process.env.NODE_ENV !== 'production') {
    console[level === 'error' ? 'error' : 'log'](logMessage);
  }

  // Log to file
  const logFile = path.join(logDir, `${level}.log`);
  fs.appendFileSync(logFile, logMessage + '\n', 'utf8');
};

module.exports = {
  info: (message, metadata) => log('info', message, metadata),
  warn: (message, metadata) => log('warn', message, metadata),
  error: (message, metadata) => log('error', message, metadata),
  debug: (message, metadata) => {
    if (process.env.NODE_ENV === 'development') {
      log('debug', message, metadata);
    }
  },
};

