## Code Examples Comparison

### Example 1: Simple Endpoint

#### BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

#### AFTER (Secure)
```javascript
app.get('/users', sensitiveEndpointLimiter, (req, res, next) => {
  try {
    // 1. Validate input
    const allowedParams = ['limit', 'offset', 'role'];
    const validationErrors = validateQueryParams(allowedParams, req.query);
    if (validationErrors) {
      logger.warn('Invalid parameters', { requestId: req.id, errors: validationErrors });
      return res.status(400).json({ error: 'Invalid parameters', details: validationErrors });
    }

    // 2. Type and range validation
    let limit = parseInt(req.query.limit, 10) || 10;
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({ error: 'Invalid limit parameter' });
    }

    let offset = parseInt(req.query.offset, 10) || 0;
    if (!Number.isInteger(offset) || offset < 0) {
      return res.status(400).json({ error: 'Invalid offset parameter' });
    }

    // 3. Enum validation
    const allowedRoles = ['user', 'admin', 'moderator'];
    if (req.query.role && !allowedRoles.includes(req.query.role)) {
      return res.status(400).json({ error: 'Invalid role parameter' });
    }

    // 4. Get data
    let data = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    // 5. Filter
    if (req.query.role) {
      data = data.filter(u => u.role === req.query.role);
    }

    // 6. Paginate
    const result = data.slice(offset, offset + limit);

    // 7. Sanitize output
    const sanitized = result.map(u => ({
      id: u.id,
      name: u.name,
      email: validator.escape(u.email),
      role: u.role,
    }));

    // 8. Return response
    res.status(200).json({
      data: sanitized,
      pagination: { offset, limit, total: data.length },
      requestId: req.id,
    });
  } catch (error) {
    logger.error('Error fetching users', { requestId: req.id, error: error.message });
    next(error);
  }
});
```

