// Improved secure version of app.js with error handling and input validation
// This version incorporates security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// LOGGING SETUP
// ============================================================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Set security HTTP headers
app.use(helmet());

// 2. CORS - Restrict cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// 3. Body parser with size limits
app.use(express.json({ 
  limit: process.env.JSON_LIMIT || '1kb',
  strict: true,
}));
app.use(express.urlencoded({ 
  limit: process.env.URL_LIMIT || '1kb',
  extended: false,
}));

// 4. Rate limiting
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000'), // 15 minutes
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100'),
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'development',
});
app.use(limiter);

// Stricter limiter for auth endpoints (if implemented)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit to 5 requests per windowMs
  skipSuccessfulRequests: true,
});

// ============================================================================
// REQUEST LOGGING MIDDLEWARE
// ============================================================================
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration,
      ip: req.ip,
    });
  });

  next();
});

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn({
      path: req.path,
      errors: errors.array(),
      ip: req.ip,
    });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health Check Endpoint
 * GET /health
 * Returns service status
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

/**
 * Get Users Endpoint
 * GET /users
 * Returns a list of users (simplified - no sensitive data exposed)
 * 
 * Query Parameters (optional):
 * - limit: number of records to return (1-100, default: 10)
 * - offset: number of records to skip (default: 0)
 */
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Mock data (would come from database in real application)
      const allUsers = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      // Paginate and return only non-sensitive fields
      const users = allUsers.slice(offset, offset + limit);

      res.json({
        data: users,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      logger.error('Get users error:', error);
      res.status(500).json({ 
        error: NODE_ENV === 'production' 
          ? 'Internal Server Error' 
          : error.message 
      });
    }
  }
);

/**
 * Example POST endpoint with input validation
 * POST /users
 * Create a new user (authentication would be required in production)
 */
app.post(
  '/users',
  authLimiter,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(), // Prevent XSS
    body('email')
      .trim()
      .isEmail()
      .withMessage('Valid email is required')
      .normalizeEmail()
      .toLowerCase(),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      // In production: validate authentication, check database, etc.
      const { name, email } = req.body;

      logger.info(`User creation attempted: ${email}`);

      // Mock response
      res.status(201).json({
        data: {
          id: 3,
          name,
          // Note: Email not returned in list response for security
        },
      });
    } catch (error) {
      logger.error('Create user error:', error);
      res.status(500).json({ 
        error: NODE_ENV === 'production' 
          ? 'Internal Server Error' 
          : error.message 
      });
    }
  }
);

// ============================================================================
// 404 HANDLER
// ============================================================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
  });
});

// ============================================================================
// GLOBAL ERROR HANDLER
// ============================================================================
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  const status = err.status || err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({
    error: message,
    ...(NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ============================================================================
// PROCESS ERROR HANDLERS
// ============================================================================
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  // In production, you might want to restart the process
  if (NODE_ENV === 'production') {
    process.exit(1);
  }
});

// ============================================================================
// SERVER STARTUP
// ============================================================================
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

// Example test suite for the improved app
// Tests for error handling, input validation, and security

const request = require('supertest');
const app = require('./app_improved');

describe('Security and Error Handling Tests', () => {

  // ========================================================================
  // HEALTH CHECK TESTS
  // ========================================================================
  describe('GET /health', () => {
    it('should return 200 with status ok', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.body.status).toBe('ok');
      expect(response.body.timestamp).toBeDefined();
    });
  });

  // ========================================================================
  // GET /users TESTS - Input Validation
  // ========================================================================
  describe('GET /users', () => {
    it('should return 200 with user data', async () => {
      const response = await request(app)
        .get('/users')
        .expect(200);

      expect(response.body.data).toBeDefined();
      expect(Array.isArray(response.body.data)).toBe(true);
      expect(response.body.pagination).toBeDefined();
    });

    it('should validate limit parameter', async () => {
      const response = await request(app)
        .get('/users?limit=invalid')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
      expect(response.body.details).toBeDefined();
    });

    it('should reject limit > 100', async () => {
      const response = await request(app)
        .get('/users?limit=101')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    it('should accept valid limit parameter', async () => {
      const response = await request(app)
        .get('/users?limit=10&offset=0')
        .expect(200);

      expect(response.body.pagination.limit).toBe(10);
      expect(response.body.pagination.offset).toBe(0);
    });

    it('should reject negative offset', async () => {
      const response = await request(app)
        .get('/users?offset=-1')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    it('should NOT expose sensitive data (email)', async () => {
      const response = await request(app)
        .get('/users')
        .expect(200);

      response.body.data.forEach(user => {
        expect(user.email).toBeUndefined();
      });
    });
  });

  // ========================================================================
  // POST /users TESTS - Input Validation & Security
  // ========================================================================
  describe('POST /users', () => {
    it('should create user with valid data', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'John Doe',
          email: 'john@example.com',
        })
        .expect(201);

      expect(response.body.data).toBeDefined();
      expect(response.body.data.name).toBe('John Doe');
    });

    it('should validate required name field', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          email: 'john@example.com',
        })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    it('should validate name length', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'a'.repeat(101),
          email: 'john@example.com',
        })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    it('should validate email format', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'John Doe',
          email: 'invalid-email',
        })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    it('should sanitize user input (prevent XSS)', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: '<script>alert("xss")</script>',
          email: 'john@example.com',
        })
        .expect(201);

      // Name should be escaped
      expect(response.body.data.name).not.toContain('<script>');
    });

    it('should normalize email to lowercase', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'John Doe',
          email: 'JOHN@EXAMPLE.COM',
        })
        .expect(201);

      // Email should be normalized (tested via logging or response)
      expect(response.statusCode).toBe(201);
    });

    it('should reject oversized payloads', async () => {
      const largePayload = {
        name: 'A'.repeat(10000),
        email: 'john@example.com',
      };

      const response = await request(app)
        .post('/users')
        .send(largePayload);

      // Should reject due to size limit
      expect(response.statusCode).toBeGreaterThanOrEqual(400);
    });
  });

  // ========================================================================
  // SECURITY TESTS - Headers & CORS
  // ========================================================================
  describe('Security Headers', () => {
    it('should include security headers from helmet', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('DENY');
      expect(response.headers['x-xss-protection']).toBeDefined();
    });

    it('should include CORS headers', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });
  });

  // ========================================================================
  // 404 TESTS
  // ========================================================================
  describe('404 Not Found', () => {
    it('should return 404 for unknown routes', async () => {
      const response = await request(app)
        .get('/unknown-route')
        .expect(404);

      expect(response.body.error).toBe('Not Found');
      expect(response.body.path).toBe('/unknown-route');
    });
  });

  // ========================================================================
  // RATE LIMITING TESTS
  // ========================================================================
  describe('Rate Limiting', () => {
    it('should include rate limit headers', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['ratelimit-limit']).toBeDefined();
      expect(response.headers['ratelimit-remaining']).toBeDefined();
    });
  });
});

# Migration Guide: From Original to Secure app.js

This guide helps you migrate your existing Express app to use security best practices.

## Option 1: Complete Replacement (Recommended for New Projects)

### Step 1: Backup
```bash
cp app.js app.js.bak
```

### Step 2: Install Dependencies
```bash
npm install express helmet cors express-rate-limit express-validator winston dotenv
npm install --save-dev nodemon eslint eslint-plugin-security jest supertest
```

### Step 3: Create .env
```bash
cp .env.example .env
# Edit .env with your configuration
```

### Step 4: Replace app.js
```bash
cp app_improved.js app.js
```

### Step 5: Update package.json scripts
```json
{
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development nodemon app.js",
    "test": "jest"
  }
}
```

### Step 6: Run Tests
```bash
npm test
```

---

## Option 2: Gradual Integration (Recommended for Existing Projects)

### Phase 1: Add Security Headers (Hour 1)
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### Phase 2: Add Error Handling (Hour 2)
```javascript
// Add at the end of all routes
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.status || 500).json({
    error: 'Internal Server Error'
  });
});
```

### Phase 3: Add Rate Limiting (Hour 3)
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

### Phase 4: Add CORS (Hour 4)
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',')
}));
```

### Phase 5: Add Input Validation (Hour 5)
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  [
    query('limit').optional().isInt({ min: 1, max: 100 })
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... rest of handler
  }
);
```

### Phase 6: Add Logging (Hour 6)
```javascript
const winston = require('winston');
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.Console()
  ]
});
```

### Phase 7: Add Body Limits & Config (Hour 7)
```javascript
require('dotenv').config();
app.use(express.json({ limit: '1kb' }));
const PORT = process.env.PORT || 3000;
```

---

## Comparison: Before vs After

### Before
```javascript
const express = require('express');
const app = express();

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

**Vulnerabilities:**
- ❌ No error handling
- ❌ No input validation
- ❌ No security headers
- ❌ No rate limiting
- ❌ No logging
- ❌ Sensitive data exposed
- ❌ No CORS control
- ❌ No request size limits

### After
```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const winston = require('winston');
require('dotenv').config();

const app = express();
const logger = winston.createLogger({ /* ... */ });

app.use(helmet());
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') }));
app.use(express.json({ limit: '1kb' }));
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

app.get('/users',
  [
    query('limit').optional().isInt({ min: 1, max: 100 }),
    query('offset').optional().isInt({ min: 0 })
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Validation failed' });
    }
    try {
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' }
      ];
      res.json({ data: users });
    } catch (error) {
      logger.error(error);
      res.status(500).json({ error: 'Internal Server Error' });
    }
  }
);

app.use((err, req, res, next) => {
  logger.error(err);
  res.status(err.status || 500).json({ error: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => logger.info(`Server on ${PORT}`));

module.exports = app;
```

**Improvements:**
- ✅ Global error handling
- ✅ Input validation
- ✅ Security headers (helmet)
- ✅ Rate limiting
- ✅ Structured logging
- ✅ Minimal data exposure
- ✅ CORS control
- ✅ Request size limits
- ✅ Environment configuration
- ✅ Graceful error responses

---

## Breaking Changes to Be Aware Of

### 1. User Endpoint Response Change
**Before:**
```json
[
  { "id": 1, "name": "Alice", "email": "alice@example.com" },
  { "id": 2, "name": "Bob", "email": "bob@example.com" }
]
```

**After:**
```json
{
  "data": [
    { "id": 1, "name": "Alice" },
    { "id": 2, "name": "Bob" }
  ],
  "pagination": {
    "limit": 10,
    "offset": 0,
    "total": 2
  }
}
```

**Migration Path for Clients:**
1. Update your client code to access `response.data` instead of `response` directly
2. Handle the new pagination object
3. Don't rely on email field (no longer returned)

### 2. Query Parameter Support
**Before:** No query parameter validation

**After:** 
- `?limit=N` (1-100) - Number of results
- `?offset=N` (>= 0) - Pagination offset
- Invalid values return 400 Bad Request

**Migration Path for Clients:**
1. Use only valid query parameters
2. Handle 400 Bad Request responses
3. Update pagination logic

### 3. Rate Limiting
**Before:** No rate limiting

**After:** 100 requests per 15 minutes per IP

**Migration Path:**
1. Monitor rate limit headers: `RateLimit-Limit`, `RateLimit-Remaining`
2. Implement backoff strategy in clients
3. Request rate limit exceptions if needed

### 4. Error Response Format
**Before:**
```
Internal server error (no response)
```

**After:**
```json
{
  "error": "Validation failed",
  "details": [...]
}
```

**Migration Path for Clients:**
1. Check for `error` field instead of assuming success
2. Parse `details` array for validation errors
3. Implement proper error handling

