const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') 
    || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
};
app.use(cors(corsOptions)); // ✅ Only allows configured origins
```

---

### Rate Limiting

**BEFORE:**
```javascript
