app.get('/users', (req, res) => { ... });
```

**AFTER:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter); // ✅ Rate limiting on all routes
```

---

### Request Size Limits

**BEFORE:**
```javascript
app.use(express.json());
// ❌ No size limit - vulnerable to buffer overflow
```

**AFTER:**
```javascript
app.use(express.json({ limit: '1kb', strict: true }));
app.use(express.urlencoded({ limit: '1kb', extended: false }));
// ✅ Prevents large payloads
```

---

### Logging

**BEFORE:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
  // ❌ Only basic console logging
});
```

**AFTER:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console(),
  ],
});

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: Date.now() - start,
    });
  });
  next();
});
// ✅ Structured logging with file persistence
```

---

### Data Protection

**BEFORE:**
```javascript
