/**
 * Improved Express Application with Security Best Practices
 * Implements: Input validation, error handling, security headers, rate limiting, logging
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const joi = require('joi');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// MIDDLEWARE: Security & Configuration
// ============================================================================

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration - Restrict to trusted origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600,
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// 3. Request Logging (Morgan)
const morganFormat = NODE_ENV === 'production' ? 'combined' : 'dev';
app.use(morgan(morganFormat));

// 4. Body Parser with Size Limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  handler: (req, res) => {
    res.status(429).json({
      status: 'error',
      code: 'RATE_LIMIT_EXCEEDED',
      message: 'Too many requests. Please try again later.',
      timestamp: new Date().toISOString(),
    });
  },
});

// Apply rate limiting to all requests
app.use(limiter);

// Stricter rate limiting for auth endpoints (if added in future)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// ============================================================================
// VALIDATION SCHEMAS
// ============================================================================

const healthCheckSchema = joi.object({
  // Can be extended with query parameters if needed
});

const userQuerySchema = joi.object({
  id: joi.number().integer().min(1).optional(),
  name: joi.string().trim().max(100).optional(),
  email: joi.string().email().optional(),
  limit: joi.number().integer().min(1).max(100).default(10),
  offset: joi.number().integer().min(0).default(0),
});

// ============================================================================
// MIDDLEWARE: Request Validation
// ============================================================================

/**
 * Validates query parameters against a schema
 */
const validateQuery = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query, {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const details = error.details.map((detail) => ({
        field: detail.path.join('.'),
        message: detail.message,
      }));

      return res.status(400).json({
        status: 'error',
        code: 'VALIDATION_ERROR',
        message: 'Invalid query parameters',
        details,
        timestamp: new Date().toISOString(),
      });
    }

    req.query = value;
    next();
  };
};

/**
 * Validates request body against a schema
 */
const validateBody = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const details = error.details.map((detail) => ({
        field: detail.path.join('.'),
        message: detail.message,
      }));

      return res.status(400).json({
        status: 'error',
        code: 'VALIDATION_ERROR',
        message: 'Invalid request body',
        details,
        timestamp: new Date().toISOString(),
      });
    }

    req.body = value;
    next();
  };
};

// ============================================================================
// ROUTES: Health Check
