];

/**
 * GET /api/v1/users
 * Retrieve users with optional filtering
 * Query Parameters:
 *   - id (number): Filter by user ID
 *   - name (string): Filter by name
 *   - email (string): Filter by email
 *   - limit (number): Max results (default: 10, max: 100)
 *   - offset (number): Pagination offset (default: 0)
 * @returns {Object} Array of users and pagination info
 */
app.get('/api/v1/users', validateQuery(userQuerySchema), (req, res) => {
  try {
    const { id, name, email, limit, offset } = req.query;

    // Filter users based on query parameters
    let filtered = [...users];

    if (id) {
      filtered = filtered.filter((u) => u.id === id);
    }

    if (name) {
      const nameLower = name.toLowerCase();
      filtered = filtered.filter((u) =>
        u.name.toLowerCase().includes(nameLower)
      );
    }

    if (email) {
      const emailLower = email.toLowerCase();
      filtered = filtered.filter((u) =>
        u.email.toLowerCase().includes(emailLower)
      );
    }

    // Apply pagination
    const total = filtered.length;
    const paginatedUsers = filtered.slice(offset, offset + limit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        total,
        limit,
        offset,
        hasMore: offset + limit < total,
      },
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    return res.status(500).json({
      status: 'error',
      code: 'INTERNAL_SERVER_ERROR',
      message: 'Failed to retrieve users',
      timestamp: new Date().toISOString(),
    });
  }
});

/**
 * GET /api/v1/users/:id
 * Retrieve a specific user by ID
 * @param {number} id - User ID
 * @returns {Object} User details or 404 error
 */
app.get('/api/v1/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID format
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        status: 'error',
        code: 'INVALID_ID',
        message: 'Invalid user ID format',
        timestamp: new Date().toISOString(),
      });
    }

    const user = users.find((u) => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        code: 'NOT_FOUND',
        message: 'User not found',
        timestamp: new Date().toISOString(),
      });
    }

    res.json({
      status: 'success',
      data: user,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    return res.status(500).json({
      status: 'error',
      code: 'INTERNAL_SERVER_ERROR',
      message: 'Failed to retrieve user',
      timestamp: new Date().toISOString(),
    });
  }
});

// ============================================================================
// MIDDLEWARE: 404 Handler
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    code: 'NOT_FOUND',
    message: 'Endpoint not found',
    path: req.originalUrl,
    timestamp: new Date().toISOString(),
  });
});

// ============================================================================
// MIDDLEWARE: Global Error Handler
// ============================================================================

/**
 * Centralized error handling middleware
 * Must be defined after all other middlewares and routes
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Determine status code
  const status = err.status || err.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  // In production, don't expose internal error details
  const message =
    status === 500 && !isDevelopment
      ? 'Internal server error'
      : err.message || 'An error occurred';

  const errorResponse = {
    status: 'error',
    code: err.code || 'INTERNAL_SERVER_ERROR',
    message,
    timestamp: new Date().toISOString(),
  };

  // Include stack trace only in development
  if (isDevelopment && err.stack) {
    errorResponse.stack = err.stack;
  }

  res.status(status).json(errorResponse);
});

