### 4. **Missing Authentication & Authorization**
**Severity: HIGH**

**Current Issues:**
- All endpoints are public (including sensitive `/users` endpoint)
- No authentication mechanism
- No authorization checks
- User data is exposed without access control

**Recommendations:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware for authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Middleware for authorization
const authorize = (allowedRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (allowedRoles.length && !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// Protect sensitive endpoints
app.get('/users', authenticateToken, authorize(['admin']), (req, res, next) => {
  try {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    next(error);
  }
});
```

