// Secure application with proper error handling, input validation, and security best practices
// This is an improved version of app.js with security hardening

require('dotenv').config();
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongoose-sanitize');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// ============================================================================
// ENVIRONMENT VALIDATION
// ============================================================================
const requiredEnvVars = ['NODE_ENV', 'JWT_SECRET'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    console.error(`FATAL: Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    }
  },
  frameguard: { action: 'deny' },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  noSniff: true,
  xssFilter: true
}));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health check
    return req.path === '/health';
  }
});
app.use('/api/', limiter);

// Request logging
const morganFormat = ':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" :response-time ms';
app.use(morgan(morganFormat, {
  skip: (req) => req.path === '/health',
  stream: process.stdout
}));

// ============================================================================
// AUTHENTICATION & AUTHORIZATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to verify JWT token
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({
      error: {
        message: 'Authentication token required',
        code: 'MISSING_AUTH_TOKEN'
      }
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    const statusCode = error.name === 'TokenExpiredError' ? 401 : 403;
    const message = error.name === 'TokenExpiredError' 
      ? 'Token has expired' 
      : 'Invalid or malformed token';

    return res.status(statusCode).json({
      error: {
        message,
        code: error.name
      }
    });
  }
};

/**
 * Middleware to authorize based on user roles
 */
const authorize = (allowedRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        error: {
          message: 'Authentication required',
          code: 'NOT_AUTHENTICATED'
        }
      });
    }

    if (allowedRoles.length && !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({
        error: {
          message: 'Insufficient permissions for this resource',
          code: 'INSUFFICIENT_PERMISSIONS'
        }
      });
    }

    next();
  };
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (public, no rate limiting)
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV
    });
  } catch (error) {
    res.status(500).json({
      error: {
        message: 'Health check failed',
        code: 'HEALTH_CHECK_ERROR'
      }
    });
  }
});

/**
 * Get all users (protected endpoint - requires authentication and admin role)
 */
app.get('/api/users', authenticateToken, authorize(['admin']), async (req, res, next) => {
  try {
    // In a real application, this would fetch from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' }
    ];

    res.json({
      success: true,
      data: users,
      meta: {
        total: users.length,
        returned: users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get user by ID (protected endpoint)
 */
app.get('/api/users/:id',
  authenticateToken,
  query('id').optional().isInt().toInt(),
  async (req, res, next) => {
    try {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: {
            message: 'Invalid input parameters',
            code: 'INVALID_INPUT',
            details: errors.array()
          }
        });
      }

      const { id } = req.params;

      // Validate ID parameter
      if (!Number.isInteger(parseInt(id)) || parseInt(id) <= 0) {
        return res.status(400).json({
          error: {
            message: 'Invalid user ID format',
            code: 'INVALID_ID_FORMAT'
          }
        });
      }

      // Mock user lookup
      const users = {
        1: { id: 1, name: 'Alice', email: 'alice@example.com' },
        2: { id: 2, name: 'Bob', email: 'bob@example.com' }
      };

      const user = users[id];

      if (!user) {
        return res.status(404).json({
          error: {
            message: 'User not found',
            code: 'USER_NOT_FOUND'
          }
        });
      }

      res.json({
        success: true,
        data: user
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      code: 'NOT_FOUND',
      path: req.path,
      method: req.method
    }
  });
});

// ============================================================================
// CENTRALIZED ERROR HANDLER
// ============================================================================

app.use((err, req, res, next) => {
  // Log error with context (avoid logging sensitive data)
  const errorLog = {
    timestamp: new Date().toISOString(),
    error: err.message,
    code: err.code || 'INTERNAL_ERROR',
    path: req.path,
    method: req.method,
    userId: req.user?.id || 'anonymous',
    statusCode: err.statusCode || 500
  };

  // Log to console in development, to logging service in production
  if (process.env.NODE_ENV === 'development') {
    console.error('Error:', errorLog);
    console.error('Stack:', err.stack);
  } else {
    // In production, send to logging service (e.g., Winston, Sentry, etc.)
    console.error(JSON.stringify(errorLog));
  }

  // Determine appropriate HTTP status code
  const statusCode = err.statusCode || (err.name === 'ValidationError' ? 400 : 500);

  // Send error response (never expose internal details in production)
  const response = {
    error: {
      message: process.env.NODE_ENV === 'production'
        ? 'An error occurred processing your request'
        : err.message,
      code: err.code || 'INTERNAL_ERROR'
    }
  };

  // Include stack trace in development only
  if (process.env.NODE_ENV !== 'production') {
    response.error.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV}`);
  });
}

module.exports = app;

