# Quick Start: Security Implementation Examples

## 1. Basic Setup with Helmet & CORS

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Add security headers
app.use(helmet());

// Configure CORS
app.use(cors({
  origin: ['http://localhost:3000'],
  credentials: true
}));

// Request body size limits
app.use(express.json({ limit: '10kb' }));
```

## 2. Input Validation Examples

```javascript
const { query, body, param, validationResult } = require('express-validator');

// Validate query parameters
app.get('/search', 
  query('q').isLength({ min: 2, max: 100 }).trim().escape(),
  query('page').optional().isInt({ min: 1 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process validated data
  }
);

// Validate POST body
app.post('/users',
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).trim(),
  body('name').notEmpty().trim().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Create user
  }
);

// Validate URL parameters
app.get('/users/:id',
  param('id').isInt().toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Get user
  }
);
```

## 3. JWT Authentication

```javascript
const jwt = require('jsonwebtoken');

// Generate token (on login)
function generateToken(userId, role) {
  return jwt.sign(
    { userId, role },
    process.env.JWT_SECRET,
    { expiresIn: '24h' }
  );
}

// Verify token middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Usage
app.post('/login', async (req, res) => {
  // Authenticate user
  const user = { id: 1, role: 'admin' };
  const token = generateToken(user.id, user.role);
  res.json({ token });
});

app.get('/protected', authenticateToken, (req, res) => {
  res.json({ user: req.user });
});
```

## 4. Role-Based Authorization

```javascript
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!requiredRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// Usage
app.delete('/admin/users/:id',
  authenticateToken,
  authorize(['admin']),
  (req, res) => {
    // Only admins can delete users
  }
);

app.get('/profile',
  authenticateToken,
  authorize(['admin', 'user']),
  (req, res) => {
    // Both admins and regular users can view profiles
  }
);
```

## 5. Error Handling Middleware

```javascript
// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
  }
}

// Route handler with error handling
app.get('/users/:id', async (req, res, next) => {
  try {
    const id = req.params.id;

    if (!id) {
      throw new AppError('User ID required', 400);
    }

    // Simulate database lookup
    const user = null;
    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json(user);
  } catch (error) {
    next(error);
  }
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'An error occurred'
    : err.message;

  res.status(statusCode).json({
    error: {
      message,
      code: err.code || 'ERROR',
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  });

  // Log error
  console.error({
    timestamp: new Date(),
    statusCode,
    message: err.message,
    path: req.path
  });
});
```

## 6. Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
});

// Strict limiter for login attempts
const loginLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, try again later'
});

app.use(generalLimiter);
app.post('/login', loginLimiter, (req, res) => {
  // Login logic
});
```

## 7. SQL Injection Prevention

```javascript
// ❌ WRONG - Vulnerable
app.get('/users/:name', (req, res) => {
  const query = `SELECT * FROM users WHERE name = '${req.params.name}'`;
  // Attacker could pass: ' OR '1'='1
});

// ✅ CORRECT - Using parameterized queries (with mysql2)
const mysql = require('mysql2/promise');

app.get('/users/:name', async (req, res, next) => {
  try {
    const conn = await mysql.createConnection(process.env.DATABASE_URL);
    const [rows] = await conn.execute(
      'SELECT * FROM users WHERE name = ?',
      [req.params.name]
    );
    res.json(rows);
  } catch (error) {
    next(error);
  }
});

// ✅ CORRECT - Using MongoDB with Mongoose
const User = require('./models/User');

app.get('/users/:name', async (req, res, next) => {
  try {
    const users = await User.find({ name: req.params.name });
    res.json(users);
  } catch (error) {
    next(error);
  }
});
```

