## Common Patterns to Avoid

```javascript
// ❌ DON'T: Expose error stack traces
app.use((err, req, res, next) => {
  res.status(500).json({ error: err.stack });
});

// ❌ DON'T: Log sensitive data
console.log('User login:', { username, password });

// ❌ DON'T: Use string concatenation for database queries
const query = `SELECT * FROM users WHERE id = ${userId}`;

// ❌ DON'T: Trust user input
app.get('/search', (req, res) => {
  res.json({ results: executeQuery(req.query.q) });
});

// ❌ DON'T: Use weak tokens
const token = Date.now().toString();

// ❌ DON'T: Store passwords in plain text
users.push({ email, password });

// ❌ DON'T: Expose internal server paths
app.use((err, req, res, next) => {
  res.status(500).json({ path: err.stack });
});

// ❌ DON'T: Allow unrestricted CORS
app.use(cors());
```

