// Improved application with security best practices
// Error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers (Helmet)
app.use(helmet());

// 2. Body Parser Limits (prevent DoS attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30, // stricter limit for sensitive endpoints
  message: 'Too many API requests, please try again later.',
});

app.use(limiter);
app.use('/api/', apiLimiter);

// 4. Request Logging (structured)
app.use(morgan('combined'));

// ============================================================================
// CUSTOM MIDDLEWARE
// ============================================================================

// Request validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// Request timeout middleware
const requestTimeout = (req, res, next) => {
  req.setTimeout(5000, () => {
    res.status(408).json({
      status: 'error',
      message: 'Request timeout'
    });
  });
  next();
};

// Request ID tracking middleware
const requestIdMiddleware = (req, res, next) => {
  req.id = req.headers['x-request-id'] || generateRequestId();
  res.set('X-Request-ID', req.id);
  next();
};

// ============================================================================
// MIDDLEWARE APPLICATION
// ============================================================================

app.use(requestTimeout);
app.use(requestIdMiddleware);

// ============================================================================
// AUTHENTICATION MIDDLEWARE (Example: Simple API Key)
// ============================================================================

const authenticateApiKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({
      status: 'error',
      message: 'Missing API key'
    });
  }

  // In production, validate against database
  const validApiKeys = process.env.VALID_API_KEYS?.split(',') || [];

  if (!validApiKeys.includes(apiKey)) {
    return res.status(403).json({
      status: 'error',
      message: 'Invalid API key'
    });
  }

  next();
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check (no auth required)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      requestId: req.id
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      requestId: req.id
    });
  }
});

// Protected users endpoint with input validation
app.get('/api/users',
  authenticateApiKey,
  [
    // Input validation
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('search')
      .optional()
      .trim()
      .isLength({ max: 50 })
      .withMessage('Search term must not exceed 50 characters')
      .matches(/^[a-zA-Z0-9\s\-@.]*$/)
      .withMessage('Search term contains invalid characters')
  ],
  validateRequest,
  (req, res) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const search = req.query.search?.toLowerCase() || '';

      // Mock database
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply search filter (case-insensitive)
      if (search) {
        users = users.filter(user =>
          user.name.toLowerCase().includes(search) ||
          user.email.toLowerCase().includes(search)
        );
      }

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const paginatedUsers = users.slice(startIndex, startIndex + limit);

      res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          pages: Math.ceil(users.length / limit)
        },
        requestId: req.id
      });
    } catch (error) {
      console.error(`[${req.id}] Error in /api/users:`, error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error',
        requestId: req.id
      });
    }
  }
);

// Create user endpoint with validation
app.post('/api/users',
  authenticateApiKey,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]*$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Must be a valid email')
      .normalizeEmail()
  ],
  validateRequest,
  (req, res) => {
    try {
      // In production, validate unique email, save to database
      const newUser = {
        id: Math.floor(Math.random() * 10000),
        name: req.body.name,
        email: req.body.email
      };

      res.status(201).json({
        status: 'success',
        message: 'User created successfully',
        data: newUser,
        requestId: req.id
      });
    } catch (error) {
      console.error(`[${req.id}] Error in POST /api/users:`, error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error',
        requestId: req.id
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    requestId: req.id
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[${req?.id}] Unhandled error:`, err);

  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV !== 'production' && { details: err.message }),
    requestId: req?.id
  });
});

// ============================================================================
// UTILITIES
// ============================================================================

function generateRequestId() {
  return `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`[${NODE_ENV}] Server running on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Before & After Comparison

## Issue 1: No Error Handling

