        requestId: req.id
      });
    } catch (error) {
      console.error(`[${req.id}] Error in /api/users:`, error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error',
        requestId: req.id
      });
    }
  }
);

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[${req?.id}] Unhandled error:`, err);
  res.status(500).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});
```

**Benefits:**
- All errors caught and handled gracefully
- Structured error responses
- Request tracking with request ID
- Environment-aware error messages

---

## Issue 2: No Input Validation

### ❌ BEFORE
```javascript
app.get('/users', (req, res) => {
  // No validation of req.query parameters
  // Accepts any input without checking
  res.json([...]);
});
```

**Vulnerabilities:**
```javascript
// All of these are accepted without validation:
/users?page=999999999              // Integer overflow
/users?limit=abc                   // Invalid type
/users?search=<script>alert()</script>  // XSS attack
/users?name=' OR '1'='1            // SQL injection attempt
```

### ✅ AFTER
```javascript
app.get('/api/users',
  authenticateApiKey,
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('search')
      .optional()
      .trim()
      .isLength({ max: 50 })
      .withMessage('Search term must not exceed 50 characters')
      .matches(/^[a-zA-Z0-9\s\-@.]*$/)
      .withMessage('Search term contains invalid characters')
  ],
  validateRequest,  // Middleware returns 400 if validation fails
  (req, res) => {
    // Guaranteed valid input here
  }
);
```

**Benefits:**
- All inputs validated before processing
- Type checking enforced
- Length limits prevent large payloads
- Regex patterns prevent injection attacks
- Clear error messages for debugging

---

## Issue 3: Missing Security Headers

### ❌ BEFORE
```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**No security headers sent:**
```
Response Headers:
X-Powered-By: Express  // Reveals framework
(missing security headers)
```

**Vulnerabilities:**
- Clickjacking attacks possible
- MIME-type sniffing
- XSS attacks not mitigated
- No transport security policy

### ✅ AFTER
```javascript
const helmet = require('helmet');

app.use(helmet());  // Adds all security headers

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Response headers now include:**
```
X-Content-Type-Options: nosniff
X-Frame-Options: DENY
X-XSS-Protection: 1; mode=block
Strict-Transport-Security: max-age=15552000; includeSubDomains
Content-Security-Policy: default-src 'self'
... (and more)
```

---

## Issue 4: No Authentication/Authorization

### ❌ BEFORE
```javascript
app.get('/users', (req, res) => {
  // Anyone can access user data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Request from anywhere:
curl http://localhost:3000/users  // ✅ Works! (Should not)
```

### ✅ AFTER
```javascript
const authenticateApiKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({
      status: 'error',
      message: 'Missing API key'
    });
  }

  const validApiKeys = process.env.VALID_API_KEYS?.split(',') || [];
  if (!validApiKeys.includes(apiKey)) {
    return res.status(403).json({
      status: 'error',
      message: 'Invalid API key'
    });
  }

  next();
};

app.get('/api/users', authenticateApiKey, (req, res) => {
  // Only authorized requests reach here
  res.json([...]);
});

// Without API key:
curl http://localhost:3000/api/users
// ❌ 401 Unauthorized

// With API key:
curl -H "X-API-Key: key_development_12345" \
  http://localhost:3000/api/users
// ✅ 200 OK
```

---

## Issue 5: No Rate Limiting

### ❌ BEFORE
```javascript
app.get('/users', (req, res) => {
  // Can be called unlimited times
  res.json([...]);
});

// Attacker can:
for (let i = 0; i < 1000000; i++) {
  fetch('http://localhost:3000/users');  // DoS attack
}
```

### ✅ AFTER
```javascript
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 30,                    // 30 requests max
  message: 'Too many requests, please try again later.',
});

app.use('/api/', apiLimiter);

app.get('/api/users', (req, res) => {
  res.json([...]);
});

// After 30 requests in 15 minutes:
// ❌ 429 Too Many Requests
```

---

## Issue 6: No Request Size Limits

### ❌ BEFORE
```javascript
app.post('/users', (req, res) => {
  // Can accept unlimited size payload
  // Attacker sends 1GB file -> memory exhaustion
  const user = req.body;
  res.json({ created: true });
});
```

### ✅ AFTER
```javascript
// Limits body size to 10KB
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));

app.post('/api/users', (req, res) => {
  // Payloads larger than 10KB rejected with 413 error
  res.json({ created: true });
});

// Large payload:
curl -X POST \
  -H "Content-Type: application/json" \
  -d '{...gigabytes of data...}' \
  http://localhost:3000/api/users
// ❌ 413 Payload Too Large
```

---

## Issue 7: No Request Timeout

### ❌ BEFORE
```javascript
app.get('/users', (req, res) => {
  // If database hangs, connection never closes
  // Attacker can exhaust all server connections
  database.query().then(data => res.json(data));
});
```

### ✅ AFTER
```javascript
const requestTimeout = (req, res, next) => {
  req.setTimeout(5000, () => {  // 5 second timeout
    res.status(408).json({
      status: 'error',
      message: 'Request timeout'
    });
  });
  next();
};

app.use(requestTimeout);

// Hanging request automatically times out after 5 seconds
```

---

## Issue 8: Exposed Sensitive Data

### ❌ BEFORE
```javascript
app.get('/users', (req, res) => {
  // Email addresses exposed without authentication
  // Anyone can scrape user emails
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### ✅ AFTER
```javascript
// 1. Require authentication
app.get('/api/users', authenticateApiKey, (req, res) => {
  res.json([...]);
});

// 2. Limit data exposure with authorization
app.get('/api/users/:id', authenticateApiKey, (req, res) => {
  // Only return data user is authorized to see
  const user = getCurrentUser(req);
  const targetUser = database.findById(req.params.id);

  if (targetUser.owner !== user.id && !user.isAdmin) {
    return res.status(403).json({
      status: 'error',
      message: 'Forbidden'
    });
  }

  res.json({ data: targetUser });
});

// 3. Don't expose unnecessary fields
res.json({
  status: 'success',
  data: {
    id: user.id,
    name: user.name,
    // Don't include: passwordHash, internalId, etc.
  }
});
```

