## Updated app.js with Environment Configuration

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ============================================================================
// CONFIGURATION
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const config = {
  server: {
    port: PORT,
    env: NODE_ENV,
    isDevelopment: NODE_ENV === 'development',
    isProduction: NODE_ENV === 'production',
  },
  security: {
    rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
    rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
    apiRateLimitMax: parseInt(process.env.API_RATE_LIMIT_MAX) || 30,
    validApiKeys: process.env.VALID_API_KEYS?.split(',').map(k => k.trim()) || [],
  },
  database: {
    host: process.env.DB_HOST || 'localhost',
    port: parseInt(process.env.DB_PORT) || 5432,
    name: process.env.DB_NAME || 'myapp',
    user: process.env.DB_USER || 'user',
    password: process.env.DB_PASSWORD || 'password',
  },
  logging: {
    level: process.env.LOG_LEVEL || 'debug',
  },
  cors: {
    origin: process.env.CORS_ORIGIN?.split(',') || ['localhost:3000'],
  },
};

// ============================================================================
// VALIDATION
// ============================================================================

// Validate critical environment variables in production
if (config.isProduction) {
  if (!process.env.VALID_API_KEYS || config.security.validApiKeys.length === 0) {
    console.error('CRITICAL: VALID_API_KEYS not configured for production!');
    process.exit(1);
  }

  if (!process.env.DB_PASSWORD) {
    console.error('CRITICAL: DB_PASSWORD not configured for production!');
    process.exit(1);
  }
}

// ============================================================================
// LOGGING
// ============================================================================

const getLogFormat = () => {
  // More verbose logging in development
  return config.isDevelopment ? 'combined' : 'short';
};

app.use(morgan(getLogFormat()));

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

app.use(helmet());
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

const limiter = rateLimit({
  windowMs: config.security.rateLimitWindow,
  max: config.security.rateLimitMax,
  message: 'Too many requests from this IP, please try again later.',
});

const apiLimiter = rateLimit({
  windowMs: config.security.rateLimitWindow,
  max: config.security.apiRateLimitMax,
  message: 'Too many API requests, please try again later.',
});

app.use(limiter);
app.use('/api/', apiLimiter);

// ============================================================================
// CUSTOM MIDDLEWARE
// ============================================================================

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      })),
      requestId: req.id
    });
  }
  next();
};

const requestTimeout = (req, res, next) => {
  req.setTimeout(5000);
  next();
};

const requestIdMiddleware = (req, res, next) => {
  req.id = req.headers['x-request-id'] || generateRequestId();
  res.set('X-Request-ID', req.id);
  next();
};

const authenticateApiKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({
      status: 'error',
      message: 'Missing API key',
      requestId: req.id
    });
  }

  if (!config.security.validApiKeys.includes(apiKey)) {
    console.warn(`[${req.id}] Invalid API key attempt: ${apiKey.substring(0, 10)}...`);
    return res.status(403).json({
      status: 'error',
      message: 'Invalid API key',
      requestId: req.id
    });
  }

  next();
};

// ============================================================================
// MIDDLEWARE APPLICATION
// ============================================================================

app.use(requestTimeout);
app.use(requestIdMiddleware);

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      env: config.env,
      requestId: req.id
    });
  } catch (error) {
    handleError(error, req, res);
  }
});

app.get('/config', authenticateApiKey, (req, res) => {
  // Show configuration (safe values only)
  try {
    res.json({
      status: 'success',
      data: {
        env: config.env,
        port: config.server.port,
        isDevelopment: config.isDevelopment,
        rateLimitMax: config.security.rateLimitMax,
      },
      requestId: req.id
    });
  } catch (error) {
    handleError(error, req, res);
  }
});

app.get('/api/users',
  authenticateApiKey,
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const startIndex = (page - 1) * limit;
      const paginatedUsers = users.slice(startIndex, startIndex + limit);

      res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
        },
        requestId: req.id
      });
    } catch (error) {
      handleError(error, req, res);
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

const handleError = (error, req, res) => {
  console.error(`[${req?.id}] Error:`, error);

  const statusCode = error.status || 500;
  const message = config.isDevelopment
    ? error.message
    : 'Internal server error';

  res.status(statusCode).json({
    status: 'error',
    message,
    requestId: req?.id
  });
};

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    requestId: req.id
  });
});

app.use((err, req, res, next) => {
  handleError(err, req, res);
});

// ============================================================================
// UTILITIES
// ============================================================================

function generateRequestId() {
  return `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`
    ╔════════════════════════════════════════╗
    ║  Server Started                        ║
    ║  Environment: ${config.env.toUpperCase().padEnd(25)} ║
    ║  Port: ${PORT.toString().padEnd(30)} ║
    ║  Rate Limit: ${config.security.rateLimitMax} req/${Math.round(config.security.rateLimitWindow / 60000)}m  ║
    ╚════════════════════════════════════════╝
  `);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received: shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;
```

