// Improved version with security best practices
// This application demonstrates proper error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================
// MIDDLEWARE - Security & Logging
// ============================================

// Security headers via helmet
app.use(helmet());

// HTTP request logging
app.use(morgan('combined'));

// Body parser with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => req.path === '/health', // Don't rate limit health checks
});

app.use(limiter);

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * No authentication required
 * Safe from rate limiting
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    // Log error but don't expose details to client
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Get users endpoint with pagination
 * Input validation and error handling included
 */
app.get(
  '/users',
  [
    // Input validation middleware
    query('skip')
      .optional()
      .isInt({ min: 0, max: 100000 })
      .toInt()
      .withMessage('skip must be a non-negative integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
    query('sortBy')
      .optional()
      .isIn(['id', 'name'])
      .withMessage('sortBy must be one of: id, name'),
  ],
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Invalid input parameters',
          details: errors.array().map((err) => ({
            param: err.param,
            message: err.msg,
          })),
        });
      }

      // Safely parse query parameters with defaults
      const skip = req.query.skip || 0;
      const limit = req.query.limit || 10;
      const sortBy = req.query.sortBy || 'id';

      // Mock data - in production, fetch from database
      let users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
        { id: 3, name: 'Charlie' },
      ];

      // Apply sorting
      if (sortBy === 'name') {
        users = users.sort((a, b) => a.name.localeCompare(b.name));
      }

      // Apply pagination
      const paginatedUsers = users.slice(skip, skip + limit);

      // Return successful response
      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          skip,
          limit,
          total: users.length,
          hasMore: skip + limit < users.length,
        },
      });
    } catch (error) {
      // Pass to error handling middleware
      next(error);
    }
  }
);

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * 404 Not Found handler
 * Must be after all other route handlers
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global error handler
 * Catches all errors from routes and middleware
 * IMPORTANT: Must have 4 parameters (err, req, res, next)
 */
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use structured logging)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Don't expose internal error details to client
  const isDevelopment = process.env.NODE_ENV === 'development';

  const errorResponse = {
    error: 'An error occurred',
    status: statusCode,
  };

  // Only include detailed error info in development
  if (isDevelopment) {
    errorResponse.message = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing server gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received: closing server gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

