// Improved application with security best practices
// Enhanced error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const morgan = require('morgan');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Set security HTTP headers
app.use(helmet());

// Prevent HTTP Parameter Pollution
app.use(hpp());

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Request logging
app.use(morgan('combined'));

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ==================== RATE LIMITING ====================

// General rate limiter: 100 requests per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter rate limiter for authentication endpoints (if added)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true,
});

// ==================== INPUT VALIDATION HELPERS ====================

/**
 * Validates query parameters
 * @param {Object} query - Query parameters
 * @returns {Object} - Validation result with errors
 */
const validateQueryParams = (query) => {
  const errors = [];

  // Check for unexpected parameters
  const allowedParams = ['page', 'limit', 'sort'];
  const queryKeys = Object.keys(query);

  queryKeys.forEach(key => {
    if (!allowedParams.includes(key)) {
      errors.push(`Unexpected parameter: ${key}`);
    }
  });

  // Validate page parameter
  if (query.page !== undefined) {
    const page = parseInt(query.page, 10);
    if (isNaN(page) || page < 1) {
      errors.push('Page must be a positive integer');
    }
  }

  // Validate limit parameter
  if (query.limit !== undefined) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('Limit must be between 1 and 100');
    }
  }

  return { isValid: errors.length === 0, errors };
};

// ==================== ERROR HANDLING MIDDLEWARE ====================

/**
 * Centralized error handler
 */
const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.message = err.message || 'Internal Server Error';

  // Log error details (avoid logging sensitive data)
  console.error({
    statusCode: err.statusCode,
    message: err.message,
    url: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Send error response
  res.status(err.statusCode).json({
    success: false,
    message: err.statusCode === 500 ? 'Internal Server Error' : err.message,
    ...(process.env.NODE_ENV === 'development' && { details: err.message }),
  });
};

// ==================== CUSTOM ERROR CLASS ====================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

// ==================== ROUTES ====================

/**
 * Health check endpoint
 */
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(new AppError('Health check failed', 500));
  }
});

/**
 * Get users endpoint with validation and error handling
 * In production: Add authentication middleware here
 */
app.get('/users', (req, res, next) => {
  try {
    // Input validation
    const { isValid, errors } = validateQueryParams(req.query);

    if (!isValid) {
      return next(new AppError(errors.join('; '), 400));
    }

    // Parse and validate pagination parameters
    const page = Math.max(1, parseInt(req.query.page || 1, 10));
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit || 10, 10)));

    // Mock database call (add try-catch for real database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Pagination
    const start = (page - 1) * limit;
    const end = start + limit;
    const paginatedUsers = allUsers.slice(start, end);

    // Sanitize response (remove sensitive fields if needed)
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      // Conditionally include email based on permissions
      email: user.email,
    }));

    res.status(200).json({
      success: true,
      data: sanitizedUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
      },
    });
  } catch (error) {
    next(new AppError(error.message || 'Failed to retrieve users', 500));
  }
});

// ==================== NOT FOUND HANDLER ====================

app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// ==================== ERROR HANDLING MIDDLEWARE ====================

app.use(errorHandler);

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;

# Security Review & Recommendations for app.js

## Executive Summary
The current application has **critical security gaps** that expose it to common attacks. This review provides a comprehensive analysis and actionable improvements.

---

## 🔴 Critical Issues

### 1. **Missing Security Headers**
**Risk Level:** HIGH  
**Impact:** Vulnerable to XSS, clickjacking, MIME-sniffing attacks

**Current State:**
- No security headers configured

**Recommendation:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds: CSP, X-Frame-Options, X-Content-Type-Options, etc.
```

---

### 2. **No Input Validation**
**Risk Level:** CRITICAL  
**Impact:** NoSQL injection, parameter pollution, type confusion attacks

**Current State:**
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
  res.json([...]);
});
```

**Recommendation:**
- Validate all input (query, body, headers, params)
- Use whitelist approach (only allow known parameters)
- Type-check all parameters
- Use libraries: `joi`, `express-validator`, `zod`

```javascript
const { validateQueryParams } = require('./validators');
app.get('/users', (req, res, next) => {
  const { isValid, errors } = validateQueryParams(req.query);
  if (!isValid) {
    return res.status(400).json({ errors });
  }
  // ... rest of code
});
```

---

### 3. **No Rate Limiting**
**Risk Level:** HIGH  
**Impact:** DoS attacks, brute force attacks, resource exhaustion

**Current State:**
- Any client can make unlimited requests

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later',
});

app.use(limiter);
```

---

### 4. **No Error Handling**
**Risk Level:** HIGH  
**Impact:** Information disclosure, unhandled crashes

**Current State:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No try-catch, no error handling
});
```

**Recommendation:**
- Wrap all route handlers in try-catch
- Implement centralized error handler
- Don't expose stack traces to clients
- Log errors for debugging

```javascript
app.get('/users', (req, res, next) => {
  try {
    // ... code
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Error middleware (must be last)
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    success: false,
    message: statusCode === 500 ? 'Internal Server Error' : err.message,
    // Only send details in development
    ...(process.env.NODE_ENV === 'development' && { details: err.message })
  });
});
```

---

### 5. **No Request Size Limits**
**Risk Level:** HIGH  
**Impact:** Memory exhaustion, DoS attacks

**Current State:**
```javascript
app.use(express.json()); // No size limit
```

**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 6. **Missing Data Sanitization**
**Risk Level:** CRITICAL  
**Impact:** NoSQL injection, data corruption

**Current State:**
- No sanitization of user input

**Recommendation:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

app.use(mongoSanitize()); // Prevents $ and . in keys
app.use(hpp()); // Prevents HTTP Parameter Pollution
```

---

### 7. **No Authentication/Authorization**
**Risk Level:** CRITICAL  
**Impact:** Unauthorized access to user data

**Current State:**
```javascript
app.get('/users', (req, res) => {
  // Anyone can access this endpoint
  res.json([...]);
});
```

**Recommendation:**
```javascript
const authenticateJWT = require('./middleware/auth');

app.get('/users', authenticateJWT, (req, res) => {
  // Only authenticated users can access
  res.json([...]);
});
```

---

### 8. **No Request Logging**
**Risk Level:** MEDIUM  
**Impact:** Inability to detect/investigate attacks

**Recommendation:**
```javascript
const morgan = require('morgan');
app.use(morgan('combined')); // Log all requests

// Custom logger for errors
const logger = {
  error: (message, error) => {
    console.error(`[ERROR] ${message}:`, error);
    // Send to log aggregation service (e.g., ELK, Splunk)
  }
};
```

---

### 9. **No HTTPS/TLS**
**Risk Level:** CRITICAL  
**Impact:** Man-in-the-middle attacks, credential theft

**Current State:**
- Only HTTP configured

**Recommendation:**
```javascript
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync('./server.key'),
  cert: fs.readFileSync('./server.crt')
};

https.createServer(options, app).listen(443);
```

Or use reverse proxy (nginx) with TLS termination.

---

### 10. **No CORS Configuration**
**Risk Level:** MEDIUM  
**Impact:** Cross-origin attacks

**Recommendation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

---

### 11. **Missing Environment Variables**
**Risk Level:** MEDIUM  
**Impact:** Configuration hardcoded, secrets exposed

**Recommendation:**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const DB_URL = process.env.DB_URL;

// Validate required environment variables
if (!process.env.DB_URL && NODE_ENV === 'production') {
  throw new Error('DB_URL environment variable is required');
}
```

