ANTHROPIC_API_KEY=sk-ant-your-api-key-here
STRIPE_SECRET_KEY=sk-test-your_key_here

# Logging & Monitoring
LOGFIRE_TOKEN=your_token_here
SENTRY_DSN=

# Feature Flags
