**Updated app.js:**
```javascript
// Load environment variables FIRST
require('dotenv').config();

const express = require('express');
const app = express();

// ==================== CONFIGURATION ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// ==================== VALIDATION ====================

// Validate required environment variables
const requiredEnvVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (NODE_ENV === 'production' && missingEnvVars.length > 0) {
  console.error('❌ Missing required environment variables:', missingEnvVars);
  process.exit(1);
}

if (missingEnvVars.length > 0) {
  console.warn('⚠️  Missing environment variables:', missingEnvVars);
}

// ==================== LOGGING ====================

const logger = {
  info: (msg) => console.log(`[${new Date().toISOString()}] INFO: ${msg}`),
  error: (msg) => console.error(`[${new Date().toISOString()}] ERROR: ${msg}`),
  warn: (msg) => console.warn(`[${new Date().toISOString()}] WARN: ${msg}`),
};

// ==================== ROUTES ====================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    port: PORT,
  });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ==================== SERVER ====================

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);

  if (NODE_ENV === 'development') {
    logger.info('Environment variables loaded:');
    logger.info(`  NODE_ENV: ${NODE_ENV}`);
    logger.info(`  PORT: ${PORT}`);
    logger.info(`  DATABASE_URL: ${process.env.DATABASE_URL ? '✓' : '✗'}`);
  }
});

// ==================== ERROR HANDLING ====================

process.on('unhandledRejection', (err) => {
  logger.error('Unhandled Rejection: ' + err.message);
  server.close(() => process.exit(1));
});

process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception: ' + err.message);
  process.exit(1);
});

module.exports = app;
```

#### 3.2 Install dotenv

```bash
npm install dotenv
```

---

### Step 4: Create Configuration Module (Optional but Recommended)

#### 4.1 Create config/environment.js

```javascript
// config/environment.js
require('dotenv').config({
  path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env'
});

const config = {
  // Application
  port: parseInt(process.env.PORT || '3000', 10),
  nodeEnv: process.env.NODE_ENV || 'development',
  logLevel: process.env.LOG_LEVEL || 'info',
  debug: process.env.DEBUG === 'true',

  // Database
  database: {
    url: process.env.DATABASE_URL,
    poolSize: parseInt(process.env.DB_POOL_SIZE || '10', 10),
  },

  // AWS
  aws: {
    region: process.env.AWS_REGION || 'us-east-1',
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },

  // APIs
  apis: {
    anthropic: process.env.ANTHROPIC_API_KEY,
    stripe: process.env.STRIPE_SECRET_KEY,
    logfire: process.env.LOGFIRE_TOKEN,
  },

  // Features
  features: {
    beta: process.env.FEATURE_BETA === 'true',
  },
};

// Validate configuration
const validateConfig = () => {
  const required = ['database.url'];

  if (config.nodeEnv === 'production') {
    required.push(
      'database.url',
      'aws.accessKeyId',
      'aws.secretAccessKey'
    );
  }

  const missing = required.filter(key => {
    const keys = key.split('.');
    let value = config;
    for (const k of keys) {
      value = value[k];
      if (!value) return true;
    }
    return false;
  });

  if (missing.length > 0) {
    throw new Error(`Missing required config: ${missing.join(', ')}`);
  }
};

try {
  validateConfig();
} catch (error) {
  console.error('Configuration Error:', error.message);
  if (config.nodeEnv === 'production') {
    process.exit(1);
  }
}

module.exports = config;
```

#### 4.2 Use in app.js

```javascript
