// Improved application with security best practices
// Error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================
// 1. SECURITY HEADERS MIDDLEWARE
// ============================================
app.use(helmet());

// ============================================
// 2. LOGGING MIDDLEWARE
// ============================================
app.use(morgan('combined'));

// ============================================
// 3. REQUEST LIMITS
// ============================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// 4. RATE LIMITING
// ============================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiter to all routes
app.use(limiter);

// More strict limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
});

// ============================================
// 5. CORS CONFIGURATION
// ============================================
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
  next();
});

// ============================================
// 6. VALIDATION MIDDLEWARE
// ============================================
const validateHealthCheck = [
  query('detailed')
    .optional()
    .isBoolean()
    .withMessage('detailed parameter must be a boolean'),
];

// ============================================
// 7. ROUTES WITH ERROR HANDLING
// ============================================

app.options('*', (req, res) => {
  res.sendStatus(200);
});

/**
 * GET /health
 * Health check endpoint with optional detailed parameter
 */
app.get('/health', validateHealthCheck, (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const detailed = req.query.detailed === 'true';

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
    };

    if (detailed) {
      response.uptime = process.uptime();
      response.memory = process.memoryUsage();
      response.environment = process.env.NODE_ENV || 'development';
    }

    res.json(response);
  } catch (error) {
    next(error);
  }
});

/**
 * GET /users
 * Get users list
 * Note: In production, this should require authentication
 */
app.get('/users', strictLimiter, (req, res, next) => {
  try {
    // TODO: Add authentication middleware in production
    // const user = req.user; // from JWT verification
    // if (!user) {
    //   return res.status(401).json({ error: 'Unauthorized' });
    // }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize response based on permissions
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // Don't expose email to non-admin users in production
      // email: user.email,
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    next(error);
  }
});

// ============================================
// 8. 404 HANDLER
// ============================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource ${req.originalUrl} was not found`,
    path: req.originalUrl,
    method: req.method,
  });
});

// ============================================
// 9. GLOBAL ERROR HANDLER
// ============================================
app.use((err, req, res, next) => {
  // Log error details (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Prepare response - don't expose sensitive details in production
  const response = {
    error: err.message || 'Internal Server Error',
    status: status,
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  // Send error response
  res.status(status).json(response);
});

// ============================================
// 10. SERVER STARTUP
// ============================================
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`[${new Date().toISOString()}] Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Catch uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Catch unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

