// Improved application with security best practices
// This version includes error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set security HTTP headers
app.use(helmet());

// Enable CORS (configure based on your needs)
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Stricter rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 requests per 15 minutes
  skipSuccessfulRequests: true, // Only count failed requests
});

// Body parser with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// HTTP request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

// Custom middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Get users endpoint with input validation
app.get('/users',
  // Query parameter validation
  [
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;

      // Mock user data - in production, this would come from a database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const users = allUsers.slice(offset, offset + limit);

      res.json({
        data: users,
        pagination: {
          limit,
          offset,
          total: allUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example: User login endpoint with rate limiting and input validation
app.post('/login',
  authLimiter,
  [
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Must be a valid email'),
    body('password')
      .isLength({ min: 8 })
      .withMessage('Password must be at least 8 characters'),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const { email, password } = req.body;

      // TODO: Implement actual authentication logic
      // - Hash password comparison (never store plain passwords!)
      // - Generate JWT or session token
      // - Return secure HTTP-only cookie or token

      res.status(200).json({
        message: 'Login endpoint - implementation required',
        email: email // Don't echo passwords!
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE (Must be last)
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handler middleware
app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  console.error('[ERROR]', {
    timestamp: new Date().toISOString(),
    status,
    message: err.message,
    stack: isDevelopment ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  // Send error response
  // In production, don't expose internal error details
  res.status(status).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} environment`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Express.js Security Best Practices Guide

## 1. INPUT VALIDATION & SANITIZATION

### ✅ DO:
```javascript
const { body, validationResult } = require('express-validator');

app.post('/user', [
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).trim(),
  body('age').isInt({ min: 0, max: 150 })
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process validated data
});
```

### ❌ DON'T:
```javascript
// Never trust user input
app.post('/user', (req, res) => {
  const { email, name } = req.body;
  // Directly use without validation - UNSAFE!
  db.saveUser(email, name);
});
```

### Key Validation Techniques:
- **Email**: Use `.isEmail()` or regex
- **Numbers**: Use `.isInt()`, `.isFloat()`
- **Strings**: Use `.trim()`, `.escape()`, `.matches(regex)`
- **Dates**: Use `.isISO8601()`
- **URLs**: Use `.isURL()`
- **Custom**: Use `.custom(value => { ... })`

---

## 2. ERROR HANDLING

### ✅ DO:
```javascript
// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const isDev = process.env.NODE_ENV === 'development';

  console.error(err);

  res.status(status).json({
    error: isDev ? err.message : 'Internal Server Error'
  });
});

// Try-catch in async routes
app.get('/data', async (req, res, next) => {
  try {
    const data = await fetchData();
    res.json(data);
  } catch (error) {
    next(error); // Pass to error handler
  }
});
```

### ❌ DON'T:
```javascript
// Exposing error details in production
res.status(500).json({ 
  error: err.stack // UNSAFE - exposes system info!
});

// No error handling - crashes server
app.get('/data', (req, res) => {
  const data = riskyOperation(); // Could throw
  res.json(data);
});
```

### Error Handling Checklist:
- ✓ Use try-catch in async functions
- ✓ Pass errors to next() in middleware
- ✓ Have a global error handler
- ✓ Log errors server-side (not to client in production)
- ✓ Return safe error messages to clients
- ✓ Handle async errors with Promise.catch()

---

## 3. SECURITY HEADERS (Helmet.js)

### ✅ DO:
```javascript
const helmet = require('helmet');
app.use(helmet()); // Enables multiple security headers

// Individual controls:
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"],
  }
}));
```

### Headers Helmet Sets:
| Header | Purpose |
|--------|---------|
| X-Content-Type-Options | Prevents MIME sniffing |
| X-Frame-Options | Prevents clickjacking |
| Strict-Transport-Security | Enforces HTTPS |
| Content-Security-Policy | Prevents XSS attacks |
| X-XSS-Protection | Legacy XSS protection |

---

## 4. RATE LIMITING & DOS PROTECTION

### ✅ DO:
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests
  standardHeaders: true,
  legacyHeaders: false,
});

// Strict limiter for auth
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts
  skipSuccessfulRequests: true, // Don't count successes
});

app.use(limiter);
app.post('/login', authLimiter, (req, res) => { /* ... */ });
```

### ❌ DON'T:
```javascript
// No rate limiting - vulnerable to brute force and DoS
app.post('/login', (req, res) => { /* ... */ });
```

---

## 5. BODY PARSER LIMITS

### ✅ DO:
```javascript
app.use(express.json({ limit: '10kb' })); // Prevent huge payloads
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

### ❌ DON'T:
```javascript
// No limits - vulnerable to memory exhaustion attacks
app.use(express.json()); // Default: unlimited
```

---

## 6. CORS CONFIGURATION

### ✅ DO:
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

### ❌ DON'T:
```javascript
// Allow all origins - exposes API to any website
app.use(cors()); // Equivalent to: origin: '*'
```

---

## 7. AUTHENTICATION & AUTHORIZATION

### ✅ DO:
```javascript
const jwt = require('jsonwebtoken');

// Middleware to verify JWT
const verifyToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Use authentication middleware on protected routes
app.get('/protected', verifyToken, (req, res) => {
  res.json({ user: req.user });
});
```

### ❌ DON'T:
```javascript
// No authentication - anyone can access
app.get('/sensitive-data', (req, res) => {
  res.json(secretData);
});

// Storing plain text passwords - NEVER!
db.savePassword(userId, plainTextPassword);
```

---

## 8. LOGGING & MONITORING

### ✅ DO:
```javascript
const morgan = require('morgan');

// HTTP request logging
app.use(morgan('combined'));

// Application logging
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Monitor uncaught errors
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Alert monitoring system
});
```

---

## 9. ENVIRONMENT VARIABLES

### ✅ DO:
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const SECRET = process.env.JWT_SECRET;
const DB_URL = process.env.DATABASE_URL;

if (!SECRET) {
  throw new Error('JWT_SECRET environment variable is required');
}
```

### ❌ DON'T:
```javascript
// Hardcoding secrets in code
const SECRET = 'my-secret-key-12345'; // UNSAFE!
const DB_URL = 'mongodb://user:pass@localhost'; // EXPOSED!
```

