});
// If JSON.stringify() fails → Server crashes!
```

### ✅ Solution
```javascript
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});
```

---

## ❌ Problem 2: No Input Validation
```javascript
// ORIGINAL - Accepts any input
app.get('/users', (req, res) => {
  res.json([...]);
});

// Attack: GET /users?limit=99999999999
// Result: Could process huge payload, causing performance issues
```

### ✅ Solution
```javascript
app.get('/users',
  [
    body('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
  ],
  handleValidationErrors,
  (req, res) => {
    const limit = parseInt(req.query.limit) || 10;
    // Now limit is guaranteed to be 1-100
    const users = allUsers.slice(0, limit);
    res.json({ data: users });
  }
);
```

---

## ❌ Problem 3: No Security Headers
```javascript
// ORIGINAL - Vulnerable to XSS, clickjacking, etc.
const app = express();
// That's it - no security headers!

// Browser receives:
// GET /
// < HTTP/1.1 200 OK
// < Content-Type: application/json
// (No security headers!)
```

### ✅ Solution
```javascript
const helmet = require('helmet');

app.use(helmet()); // Adds 15+ security headers automatically

// Browser now receives:
// < X-Content-Type-Options: nosniff (prevents MIME sniffing)
// < X-Frame-Options: DENY (prevents clickjacking)
// < Strict-Transport-Security: max-age=15552000 (forces HTTPS)
// < Content-Security-Policy: default-src 'self' (prevents XSS)
// ... and more!
```

---

## ❌ Problem 4: Exposed Sensitive Data
```javascript
// ORIGINAL - No authentication required!
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Any anonymous user can call:
// GET http://example.com/users
// Response: All users' emails exposed! 🚨
```

### ✅ Solution
```javascript
// Middleware to verify JWT token
const verifyToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Require authentication
app.get('/users', verifyToken, (req, res) => {
  // Only authenticated users can access
  res.json([...]);
});

// Anonymous request rejected:
// GET /users
// < 401 Unauthorized
// { error: 'No token' }
```

---

## ❌ Problem 5: No Rate Limiting
```javascript
// ORIGINAL - Can be DDoS'd easily
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Attack: Send 10,000 requests/second
// Result: Server overwhelmed, crashes
```

### ✅ Solution
```javascript
const rateLimit = require('express-rate-limit');

// Limit to 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
});

app.use(limiter);

// Stricter limits for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

app.post('/login', authLimiter, (req, res) => {
  // Only 5 failed attempts per 15 minutes
});

// Attack: 101st request
// < 429 Too Many Requests
// "Too many requests from this IP, please try again later."
```

---

## ❌ Problem 6: No Body Size Limits
```javascript
// ORIGINAL - Accept any size payload
app.use(express.json()); // Default: unlimited!

// Attack: Send 1GB JSON payload
// Result: Server memory exhausted, crashes
```

### ✅ Solution
```javascript
// Limit body size to 10KB
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Attack: Send 11KB payload
// < 413 Payload Too Large
// { error: 'request entity too large' }
```

---

## ❌ Problem 7: No Logging
```javascript
// ORIGINAL
app.get('/users', (req, res) => {
  res.json([...]);
});

// User reports: "API is slow"
// You have no logs to investigate! 😞
```

### ✅ Solution
```javascript
const morgan = require('morgan');

// Logs all HTTP requests
app.use(morgan('combined'));

// Console output:
// GET /users 200 5.234 ms - 156
// GET /users 200 4.892 ms - 156
// POST /login 401 2.134 ms - 32

// With timestamps and JSON:
// [2024-01-15T10:30:45.123Z] GET /users from 192.168.1.1 (200 ms)
// [2024-01-15T10:30:46.456Z] POST /login from 192.168.1.2 (Failed)
```

---

## ❌ Problem 8: Hardcoded Configuration
```javascript
// ORIGINAL - Same config for dev and production
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Problems:
// - Can't change port without code change
// - Secrets hardcoded (if any were added later)
// - Same config for dev/staging/prod
```

### ✅ Solution
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

if (!JWT_SECRET && NODE_ENV === 'production') {
  throw new Error('JWT_SECRET is required in production');
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV}`);
});
```

**`.env` file:**
```
PORT=3000
NODE_ENV=development
JWT_SECRET=my-super-secret-key
```

**Production deploy:**
```bash
export PORT=8080
export NODE_ENV=production
export JWT_SECRET=prod-secret-key-from-vault
npm start
```

---

## ❌ Problem 9: No Graceful Error Handling
```javascript
// ORIGINAL - Unhandled errors crash server
app.get('/users', (req, res) => {
  res.json([...]);
});

// If database query fails → Uncaught exception → Server dies
// Users get 500 error, and app is down
```

### ✅ Solution
```javascript
// Global error handler (last middleware)
app.use((err, req, res, next) => {
  const status = err.status || 500;

  console.error('[ERROR]', {
    timestamp: new Date().toISOString(),
    status,
    message: err.message,
    path: req.path
  });

  // Safe error response
  const isDev = process.env.NODE_ENV === 'development';
  res.status(status).json({
    error: isDev ? err.message : 'Internal Server Error'
  });
});

// Handle process-level errors
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});
```

---

## ❌ Problem 10: No Input Sanitization
```javascript
// ORIGINAL - Echoes user input directly
app.post('/search', (req, res) => {
  const query = req.body.query;
  res.json({ 
    search: `You searched for: ${query}`
    // Vulnerable to XSS!
  });
});

// Attack: POST /search
// { "query": "<img src=x onerror='alert(1)'>" }
// Response includes unescaped HTML → XSS vulnerability
```

### ✅ Solution
```javascript
const { body, validationResult } = require('express-validator');

app.post('/search', 
  body('query')
    .trim()           // Remove whitespace
    .escape()         // Escape HTML characters
    .isLength({ min: 1, max: 100 })  // Validate length
    .withMessage('Query must be 1-100 characters'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors });
    }

    const query = req.body.query; // Now safe!
    res.json({ search: `You searched for: ${query}` });
  }
);

// Attack attempt:
// { "query": "<img src=x onerror='alert(1)'>" }
// After validation & escape:
// { "search": "You searched for: &lt;img src=x onerror=&#x27;alert(1)&#x27;&gt;" }
// Safe - displayed as text, not executed
```

---

## Security Checklist: Before → After

| Security Measure | Before | After | Impact |
|------------------|--------|-------|--------|
| Error Handling | ❌ None | ✅ Global handler | Prevents crashes |
| Input Validation | ❌ None | ✅ express-validator | Prevents injection |
| Security Headers | ❌ None | ✅ Helmet.js | Prevents XSS/clickjacking |
| Authentication | ❌ None | ✅ JWT middleware | Protects sensitive data |
| Rate Limiting | ❌ None | ✅ express-rate-limit | Prevents DDoS/brute force |
| Body Size Limits | ❌ Unlimited | ✅ 10KB | Prevents memory attacks |
| Request Logging | ❌ None | ✅ Morgan | Enables debugging |
| Environment Config | ❌ Hardcoded | ✅ dotenv | Flexible deployment |
| Graceful Shutdown | ❌ None | ✅ Signal handlers | Clean cleanup |
| CORS Control | ❌ Not configured | ✅ Whitelisted origins | Prevents unauthorized access |

---

## Performance Impact

### Original
- No validation overhead
- But: No protection, data corruption possible
- Crashes cause downtime (∞ ms)

### Improved
- Small overhead: ~1-2ms per request
- But: Prevents attacks, data integrity protected
- Uptime: 99.9%+

**Trade-off is worth it for production! ✅**

