## Quick Start: Improved app.js Structure

See the accompanying `app_improved.js` file for a complete, security-hardened version of the application.

// Improved Express Application with Security Best Practices
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult, body } = require('express-validator');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Use Helmet to set various HTTP headers
app.use(helmet());

// 2. Configure CORS with allowlist
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. HTTP request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// 4. Parse JSON with size limit to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. Enforce HTTPS in production
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// 6. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => NODE_ENV !== 'production', // Skip rate limiting in development
});

app.use(limiter);

// 7. Stricter rate limit for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Very strict for auth endpoints
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
      return res.status(401).json({ 
        error: 'Unauthorized',
        message: 'Authentication token required'
      });
    }

    const user = jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key');
    req.user = user;
    next();
  } catch (error) {
    logSecurityEvent('INVALID_TOKEN', { error: error.message });
    return res.status(403).json({ 
      error: 'Forbidden',
      message: 'Invalid or expired token'
    });
  }
};

// ============================================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================================

const requireRole = (role) => {
  return (req, res, next) => {
    if (!req.user || req.user.role !== role) {
      logSecurityEvent('UNAUTHORIZED_ROLE_ACCESS', { 
        userId: req.user?.id, 
        requiredRole: role,
        userRole: req.user?.role 
      });
      return res.status(403).json({ 
        error: 'Forbidden',
        message: `This action requires ${role} role`
      });
    }
    next();
  };
};

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Log security events for monitoring
 */
const logSecurityEvent = (event, details = {}) => {
  console.log(`[SECURITY] ${new Date().toISOString()} - ${event}:`, details);
};

/**
 * Filter sensitive user data based on requester permissions
 */
const filterUserData = (user, requestingUser) => {
  const filtered = {
    id: user.id,
    name: user.name
  };

  // Only include email if:
  // 1. Requesting user is admin, OR
  // 2. Requesting user is the user themselves
  if (requestingUser.role === 'admin' || requestingUser.id === user.id) {
    filtered.email = user.email;
  }

