# Security Review: app.js

## Critical Issues Found

### 1. **Missing Error Handling** ⚠️ HIGH PRIORITY
- No error handling middleware
- No try-catch blocks around operations
- Unhandled promise rejections not caught
- No 404 handler

### 2. **Missing Input Validation** ⚠️ HIGH PRIORITY
- Query parameters are never validated
- No request body validation (if POST routes added)
- No sanitization of user input
- Vulnerable to injection attacks

### 3. **Sensitive Data Exposure** ⚠️ MEDIUM
- User emails exposed in `/users` endpoint
- No rate limiting on sensitive endpoints
- No authentication/authorization checks

### 4. **Missing Security Headers** ⚠️ MEDIUM
- No helmet.js for security headers
- No CORS configuration
- No Content Security Policy

### 5. **No Request Logging/Monitoring** ⚠️ LOW
- Cannot track suspicious requests
- No request size limits
- No timeout configurations

### 6. **No Environment Configuration** ⚠️ LOW
- Hardcoded port
- No environment-based error messaging

---

## Detailed Recommendations

### Issue 1: Add Global Error Handling
```javascript
// Add error handling middleware
app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});
```

### Issue 2: Implement Input Validation
```javascript
// Use validation library like joi or express-validator
const { query, validationResult } = require('express-validator');

app.get('/users', 
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... proceed
  }
);
```

### Issue 3: Add Security Headers & CORS
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds security headers
app.use(express.json({ limit: '10kb' })); // Limit payload size
```

### Issue 4: Add Request Timeout & Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});

app.use(limiter);
app.set('trust proxy', 1); // if behind proxy
```

### Issue 5: Add Request Logging
```javascript
const morgan = require('morgan');
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));
```

### Issue 6: Handle Unhandled Rejections
```javascript
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  process.exit(1);
});
```

---

## Summary of Security Gaps

| Category | Issue | Severity | Impact |
|----------|-------|----------|--------|
| Error Handling | No error middleware | HIGH | Application crashes on errors |
| Input Validation | No validation | HIGH | Injection attacks possible |
| Authentication | No auth checks | HIGH | Unauthorized access |
| Data Protection | Exposed emails | MEDIUM | Privacy violation |
| Headers | Missing security headers | MEDIUM | XSS/Clickjacking attacks |
| Rate Limiting | None implemented | MEDIUM | DoS attacks possible |
| Logging | No request logging | LOW | Cannot audit requests |
| Environment | Hardcoded config | LOW | Not production-ready |

// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============= Security Middleware =============

// Add security headers
app.use(helmet());

// Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// Body parser with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Trust proxy if behind reverse proxy
if (process.env.TRUST_PROXY === 'true') {
  app.set('trust proxy', 1);
}

// ============= Routes =============

/**
 * Health check endpoint
 * Returns server status
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint with input validation
 * Query parameters:
 *  - limit: max number of users (1-100, default: 10)
 *  - offset: pagination offset (default: 0)
 */
app.get('/users',
  // Validate query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('offset must be a non-negative integer'),
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Invalid query parameters',
          details: errors.array() 
        });
      }

      const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset, 10) || 0, 0);

      // Mock database - in production, sanitize before DB query
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const users = allUsers.slice(offset, offset + limit);

      res.status(200).json({
        data: users,
        pagination: {
          offset,
          limit,
          total: allUsers.length,
          hasMore: offset + limit < allUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============= 404 Handler =============
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// ============= Error Handling Middleware =============
// Must be last middleware defined
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || err.status || 500;
  const isProduction = NODE_ENV === 'production';

  console.error({
    timestamp: new Date().toISOString(),
    statusCode,
    message: err.message,
    path: req.path,
    method: req.method,
    ...(process.env.LOG_STACK_TRACE === 'true' && { stack: err.stack })
  });

  res.status(statusCode).json({
    error: {
      message: isProduction 
        ? 'Internal server error' 
        : err.message,
      status: statusCode,
      ...(process.env.NODE_ENV !== 'production' && { 
        stack: err.stack 
      })
    }
  });
});

// ============= Unhandled Exception Handlers =============

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you may want to exit or report to monitoring service
  if (NODE_ENV === 'production') {
    process.exit(1);
  }
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you should exit after logging
  if (NODE_ENV === 'production') {
    process.exit(1);
  }
});

// ============= Server Startup =============
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`Health check: http://localhost:${PORT}/health`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

