  res.json({ status: 'ok' });
});
```

**AFTER:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                   // 100 requests per window
  message: 'Too many requests'
});

app.use(limiter);  // Apply to all routes

// Response headers:
// RateLimit-Limit: 100
// RateLimit-Remaining: 95
// RateLimit-Reset: 1234567890
```

### 5. Request Logging

**BEFORE:**
```javascript
// No logging - cannot audit requests
```

**AFTER:**
```javascript
const morgan = require('morgan');
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Output:
// GET /users?limit=10 200 5.234 ms - 84
// GET /health 200 1.234 ms - 45
```

### 6. Payload Size Limits

**BEFORE:**
```javascript
// Can accept unlimited payloads - memory exhaustion attack
app.use(express.json());  // No limit!
```

**AFTER:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Prevents: {
//   "data": "[VERY LARGE STRING REPEATED 1 MILLION TIMES]"
// }
```

### 7. Unhandled Exceptions

**BEFORE:**
```javascript
// Silent failures - app keeps running in broken state
// No handlers for rejections
```

**AFTER:**
```javascript
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  if (NODE_ENV === 'production') {
    process.exit(1);  // Restart app
  }
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  if (NODE_ENV === 'production') {
    process.exit(1);
  }
});
```

### 8. Graceful Shutdown

**BEFORE:**
```javascript
// No graceful shutdown
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**AFTER:**
```javascript
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle shutdown signals
process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing server');
  server.close(() => {
    console.log('Server closed gracefully');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received: closing server');
  server.close(() => {
    process.exit(0);
  });
});
```

