// Enhanced application with security best practices
// Includes error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const validator = require('validator');

const app = express();

// ===== Security Middleware =====

// Set security headers using helmet
app.use(helmet());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Parse JSON payloads with size limit
app.use(express.json({ limit: '10kb' }));

// Trust proxy - important for rate limiting behind reverse proxies
app.set('trust proxy', 1);

// ===== Logging Setup =====
const logger = {
  info: (msg) => console.log(`[INFO] ${new Date().toISOString()}: ${msg}`),
  error: (msg, err) => console.error(`[ERROR] ${new Date().toISOString()}: ${msg}`, err),
  warn: (msg) => console.warn(`[WARN] ${new Date().toISOString()}: ${msg}`),
};

// ===== Error Handling Middleware =====

/**
 * Validation error handler middleware
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

/**
 * Global error handler middleware (must be last)
 */
const errorHandler = (err, req, res, next) => {
  logger.error('Unhandled error:', err);

  // Default error response
  const response = {
    success: false,
    error: 'Internal server error',
  };

  // Log the full error details server-side only
  if (err.name === 'ValidationError') {
    response.error = 'Invalid input';
    response.details = err.message;
    return res.status(400).json(response);
  }

  // Don't expose internal error details to client
  if (process.env.NODE_ENV === 'development') {
    response.details = err.message;
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
};

// ===== Routes =====

/**
 * Health check endpoint
 * @route GET /health
 * @returns {Object} Health status and timestamp
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({
      success: true,
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    next(err);
  }
});

/**
 * Get users endpoint with optional filtering
 * @route GET /users
 * @query {string} name - Optional filter by user name (alphanumeric, 1-50 chars)
 * @query {string} email - Optional filter by user email
 * @returns {Array} Array of user objects
 */
app.get(
  '/users',
  // Validation middleware
  query('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('Name must be between 1 and 50 characters')
    .matches(/^[a-zA-Z0-9\s-]+$/)
    .withMessage('Name can only contain alphanumeric characters, spaces, and hyphens'),
  query('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  handleValidationErrors,
  (req, res, next) => {
    try {
      // Sample user data (in production, this would come from a database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      let filteredUsers = allUsers;

      // Apply filters if provided
      const { name, email } = req.query;

      if (name) {
        filteredUsers = filteredUsers.filter(u =>
          u.name.toLowerCase().includes(name.toLowerCase())
        );
      }

      if (email) {
        filteredUsers = filteredUsers.filter(u =>
          u.email.toLowerCase() === email.toLowerCase()
        );
      }

      logger.info(`Retrieved ${filteredUsers.length} users`);

      res.json({
        success: true,
        count: filteredUsers.length,
        data: filteredUsers,
      });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * Create user endpoint
 * @route POST /users
 * @body {Object} User data (name, email)
 * @returns {Object} Created user object
 */
app.post(
  '/users',
  // Validation middleware
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z0-9\s-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail(),
  handleValidationErrors,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // Additional sanitization
      const sanitizedName = validator.escape(name);
      const sanitizedEmail = validator.escape(email);

      // In production, validate against database, check duplicates, etc.
      if (!sanitizedName || !sanitizedEmail) {
        return res.status(400).json({
          success: false,
          error: 'Invalid user data',
        });
      }

      const newUser = {
        id: 3,
        name: sanitizedName,
        email: sanitizedEmail,
      };

      logger.info(`User created: ${sanitizedEmail}`);

      res.status(201).json({
        success: true,
        data: newUser,
      });
    } catch (err) {
      next(err);
    }
  }
);

// ===== 404 Handler =====
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
  });
});

// ===== Error Handler (must be last) =====
app.use(errorHandler);

// ===== Graceful Shutdown =====
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', reason);
});

process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception:', err);
  process.exit(1);
});

// ===== Server Startup =====
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;

# Security Review & Recommendations for app.js

## Executive Summary
The current application lacks critical security controls including input validation, error handling, security headers, and rate limiting. These issues expose the application to common web vulnerabilities.

---

## 1. INPUT VALIDATION & SANITIZATION

### Current Issues:
- No validation of query parameters
- No type checking
- No length limits
- Direct use of user input

### Recommendations:
✅ **Implement validation using express-validator:**
```javascript
const { query, body, validationResult } = require('express-validator');

app.get('/users', 
  query('name').optional().trim().isLength({ min: 1, max: 50 }),
  query('email').optional().isEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... process validated input
  }
);
```

✅ **Sanitize user input:**
```javascript
const validator = require('validator');
const sanitized = validator.escape(userInput);
```

✅ **Set request size limits:**
```javascript
app.use(express.json({ limit: '10kb' }));
```

---

## 2. SECURITY HEADERS

### Current Issues:
- No HTTP security headers
- Vulnerable to clickjacking (no X-Frame-Options)
- No content security policy
- Missing HSTS header

### Recommendations:
✅ **Use helmet.js for security headers:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

This automatically sets:
- `X-Frame-Options: DENY` (prevents clickjacking)
- `X-Content-Type-Options: nosniff`
- `Strict-Transport-Security: max-age=...`
- `Content-Security-Policy`
- And more...

---

## 3. ERROR HANDLING

### Current Issues:
- No error handling
- No try-catch blocks
- Unhandled promise rejections
- No centralized error handler
- Potential information disclosure

### Recommendations:
✅ **Create centralized error handler:**
```javascript
const errorHandler = (err, req, res, next) => {
  logger.error('Error:', err);

  // Don't expose internal details to client
  const response = {
    success: false,
    error: 'Internal server error',
  };

  if (process.env.NODE_ENV === 'development') {
    response.details = err.message;
  }

  res.status(err.status || 500).json(response);
};

app.use(errorHandler);
```

✅ **Wrap route handlers in try-catch:**
```javascript
app.get('/users', (req, res, next) => {
  try {
    // Route logic
  } catch (err) {
    next(err); // Pass to error handler
  }
});
```

✅ **Handle unhandled rejections:**
```javascript
process.on('unhandledRejection', (reason) => {
  logger.error('Unhandled Rejection:', reason);
  process.exit(1);
});
```

---

## 4. RATE LIMITING

### Current Issues:
- No rate limiting
- Vulnerable to brute force attacks
- Vulnerable to DoS attacks

### Recommendations:
✅ **Implement express-rate-limit:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // Limit per IP
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);
```

---

## 5. LOGGING & MONITORING

### Current Issues:
- No structured logging
- Difficult to audit and debug
- No request/response logging

### Recommendations:
✅ **Implement structured logging:**
```javascript
const logger = {
  info: (msg) => console.log(`[INFO] ${new Date().toISOString()}: ${msg}`),
  error: (msg, err) => console.error(`[ERROR] ${new Date().toISOString()}: ${msg}`, err),
  warn: (msg) => console.warn(`[WARN] ${new Date().toISOString()}: ${msg}`),
};

// Use in route handlers
logger.info(`Retrieved ${users.length} users`);
```

✅ **Consider production logging service:**
- Winston
- Bunyan
- Pino
- CloudWatch / Datadog

---

## 6. INFORMATION DISCLOSURE

### Current Issues:
- Returning generic data without validation
- Potential for SQL injection with database queries
- No data access control

### Recommendations:
✅ **Validate and sanitize all outputs:**
```javascript
const sanitized = validator.escape(data);
```

✅ **Implement response formatting:**
```javascript
res.json({
  success: true,
  data: filteredUsers,
  count: filteredUsers.length,
});
```

✅ **Never expose sensitive information:**
- Don't return passwords
- Don't expose internal server paths
- Don't return stack traces to clients
- Don't expose database query details

---

## 7. AUTHENTICATION & AUTHORIZATION

### Current Issues:
- No authentication
- No authorization checks
- Users endpoint accessible to anyone

### Recommendations:
✅ **Implement authentication (e.g., JWT):**
```javascript
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

app.get('/users', authenticate, (req, res) => {
  // Protected route
});
```

---

## 8. HTTPS/TLS

### Current Issues:
- No HTTPS configuration
- Data transmitted in plain text
- Vulnerable to man-in-the-middle attacks

### Recommendations:
✅ **Enable HTTPS in production:**
```javascript
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync('private-key.pem'),
  cert: fs.readFileSync('certificate.pem'),
};

https.createServer(options, app).listen(443);
```

✅ **Use environment variable for port:**
```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT);
```

---

## 9. ENVIRONMENT VARIABLES

### Current Issues:
- Hard-coded port
- No configuration management

### Recommendations:
✅ **Use .env file with dotenv:**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

if (!JWT_SECRET && NODE_ENV === 'production') {
  throw new Error('JWT_SECRET must be set in production');
}
```

---

## 10. CORS CONFIGURATION

### Current Issues:
- CORS not configured
- Potential cross-origin attacks

### Recommendations:
✅ **Configure CORS properly:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

---

## Required Dependencies

Add to package.json:
```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-validator": "^7.0.0",
    "validator": "^13.9.0",
    "dotenv": "^16.0.0",
    "cors": "^2.8.5"
  }
}
```

---

## Implementation Priority

### 🔴 Critical (Implement First):
1. Input validation (express-validator)
2. Error handling (centralized error handler)
3. Helmet security headers
4. Rate limiting

### 🟠 High (Implement Soon):
1. Logging
2. Request size limits
3. CORS configuration
4. Environment variables

### 🟡 Medium (Implement Before Production):
1. Authentication (JWT)
2. Authorization checks
3. HTTPS/TLS
4. Database query protection (prepared statements, ORMs)

### 🟢 Low (Nice to Have):
1. Advanced logging services
2. APM (Application Performance Monitoring)
3. Security scanning tools
4. API documentation

---

## Testing Recommendations

```bash
