// Enhanced application with security best practices
// Includes error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet - Set security HTTP headers
app.use(helmet());

// 2. Rate Limiting - Prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// 3. Body Parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 5. Data sanitization against XSS
app.use(xss());

// 6. CORS Configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// ============================================
// LOGGING MIDDLEWARE
// ============================================

const logRequest = (req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });

  next();
};

app.use(logRequest);

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

/**
 * Validates and sanitizes user ID parameter
 * @param {string} id - User ID to validate
 * @returns {object} { valid: boolean, value: number|null, error: string|null }
 */
const validateUserId = (id) => {
  if (!id) {
    return { valid: false, value: null, error: 'User ID is required' };
  }

  if (!validator.isInt(id, { min: 1 })) {
    return { valid: false, value: null, error: 'User ID must be a positive integer' };
  }

  return { valid: true, value: parseInt(id, 10), error: null };
};

/**
 * Validates email format
 * @param {string} email - Email to validate
 * @returns {object} { valid: boolean, error: string|null }
 */
const validateEmail = (email) => {
  if (!email) {
    return { valid: false, error: 'Email is required' };
  }

  if (!validator.isEmail(email)) {
    return { valid: false, error: 'Invalid email format' };
  }

  return { valid: true, error: null };
};

/**
 * Validates name input
 * @param {string} name - Name to validate
 * @returns {object} { valid: boolean, error: string|null }
 */
const validateName = (name) => {
  if (!name || typeof name !== 'string') {
    return { valid: false, error: 'Name is required and must be a string' };
  }

  const trimmedName = name.trim();

  if (trimmedName.length < 2 || trimmedName.length > 100) {
    return { valid: false, error: 'Name must be between 2 and 100 characters' };
  }

  if (!validator.matches(trimmedName, /^[a-zA-Z\s'-]+$/)) {
    return { valid: false, error: 'Name contains invalid characters' };
  }

  return { valid: true, error: null };
};

// ============================================
// IN-MEMORY DATA STORE (for demo purposes)
// ============================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

/**
 * Get all users endpoint
 * GET /users
 * Query params: skip (default 0), limit (default 10, max 100)
 */
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    let skip = 0;
    let limit = 10;

    if (req.query.skip) {
      if (!validator.isInt(req.query.skip, { min: 0 })) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid skip parameter',
          error: 'skip must be a non-negative integer',
        });
      }
      skip = parseInt(req.query.skip, 10);
    }

    if (req.query.limit) {
      if (!validator.isInt(req.query.limit, { min: 1, max: 100 })) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid limit parameter',
          error: 'limit must be an integer between 1 and 100',
        });
      }
      limit = parseInt(req.query.limit, 10);
    }

    // Apply pagination
    const paginatedUsers = users.slice(skip, skip + limit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        skip,
        limit,
        total: users.length,
      },
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get single user by ID
 * GET /users/:id
 */
app.get('/users/:id', (req, res, next) => {
  try {
    // Validate user ID
    const validation = validateUserId(req.params.id);

    if (!validation.valid) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID',
        error: validation.error,
      });
    }

    const user = users.find((u) => u.id === validation.value);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found',
      });
    }

    res.json({
      status: 'success',
      data: user,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Create a new user
 * POST /users
 * Body: { name: string, email: string }
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate input
    const nameValidation = validateName(name);
    if (!nameValidation.valid) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid name',
        error: nameValidation.error,
      });
    }

    const emailValidation = validateEmail(email);
    if (!emailValidation.valid) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid email',
        error: emailValidation.error,
      });
    }

    // Check for duplicate email
    if (users.some((u) => u.email === email)) {
      return res.status(409).json({
        status: 'error',
        message: 'Email already exists',
      });
    }

    // Create new user
    const newUser = {
      id: Math.max(...users.map((u) => u.id), 0) + 1,
      name: name.trim(),
      email: email.toLowerCase(),
    };

    users.push(newUser);

    res.status(201).json({
      status: 'success',
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    path: req.path,
  });
});

/**
 * Global error handler
 * Must be the last middleware
 */
app.use((error, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()}:`, error.message);
  console.error(error.stack);

  // Avoid leaking error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(error.status || 500).json({
    status: 'error',
    message: isDevelopment ? error.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: error.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The original app.js is a minimal Express application that lacks essential security measures. This document outlines critical vulnerabilities and provides comprehensive recommendations with implementation details.

---

## Critical Issues Found

### 1. **Missing Input Validation** ⚠️ CRITICAL
**Current State:**
- No query parameter validation
- No request body validation
- Direct access to req.params and req.body without checks

**Risks:**
- NoSQL injection attacks
- XSS (Cross-Site Scripting) attacks
- Type confusion vulnerabilities
- Buffer overflow through oversized payloads

**Recommendation:**
```javascript
// Use validator library
const validator = require('validator');

// Example validation function
const validateUserId = (id) => {
  if (!id) return { valid: false, error: 'ID required' };
  if (!validator.isInt(id, { min: 1 })) 
    return { valid: false, error: 'Invalid ID format' };
  return { valid: true, value: parseInt(id, 10) };
};
```

---

### 2. **Missing Error Handling** ⚠️ CRITICAL
**Current State:**
- No try-catch blocks
- No error middleware
- No graceful error responses
- Unhandled promise rejections possible

**Risks:**
- Server crashes on errors
- Information disclosure through stack traces
- Poor user experience
- Difficult debugging

**Recommendation:**
```javascript
// Global error handler middleware (last middleware)
app.use((error, req, res, next) => {
  console.error('Error:', error.message);

  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(error.status || 500).json({
    status: 'error',
    message: isDevelopment ? error.message : 'Internal server error',
    ...(isDevelopment && { stack: error.stack }),
  });
});

// Per-route error handling
app.get('/users/:id', (req, res, next) => {
  try {
    // Route logic
  } catch (error) {
    next(error);
  }
});
```

---

### 3. **Missing Security Headers** ⚠️ HIGH
**Current State:**
- No Content Security Policy (CSP)
- No X-Frame-Options
- No X-Content-Type-Options
- No Strict-Transport-Security (HSTS)

**Risks:**
- Clickjacking attacks
- MIME-sniffing attacks
- Man-in-the-middle attacks
- XSS vulnerabilities

**Recommendation:**
```javascript
const helmet = require('helmet');

// Add all security headers automatically
app.use(helmet());

// Or customize individually
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  noSniff: true,
}));
```

---

### 4. **No Rate Limiting** ⚠️ HIGH
**Current State:**
- No protection against brute force attacks
- No DDoS mitigation
- Unlimited requests allowed

**Risks:**
- Brute force attacks on authentication endpoints
- DDoS attacks
- Resource exhaustion
- Service unavailability

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// Global rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // 5 requests per hour
});

app.post('/login', strictLimiter, loginHandler);
```

---

### 5. **No CORS Configuration** ⚠️ MEDIUM
**Current State:**
- No CORS headers
- Allows requests from any origin

**Risks:**
- Unauthorized API access from malicious domains
- Credential theft
- Unintended data exposure

**Recommendation:**
```javascript
const cors = require('cors');

// Strict CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 3600,
}));

// Or implement custom CORS
app.use((req, res, next) => {
  const allowedOrigins = ['https://example.com', 'https://app.example.com'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  }
  next();
});
```

