});

// Validation helper
const validateUserId = (id) => {
  if (!id) {
    return { valid: false, error: 'User ID is required' };
  }

  if (!validator.isInt(id, { min: 1 })) {
    return { valid: false, error: 'User ID must be a positive integer' };
  }

  return { valid: true, value: parseInt(id, 10) };
};
