// Improved application with security best practices
// This version includes error handling, validation, and security measures

require('dotenv').config();
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// Security Middleware - Apply these before routes
// ============================================================================

// Use Helmet to set various HTTP headers for security
app.use(helmet());

// Enable CORS with configuration
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Limit request body size to prevent DoS attacks
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.RATE_LIMIT_MAX || 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks in some cases
    return req.path === '/health' && process.env.SKIP_HEALTH_RATE_LIMIT === 'true';
  }
});

app.use(limiter);

// ============================================================================
// Middleware for validation error handling
// ============================================================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// Routes
// ============================================================================

/**
 * Health check endpoint
 * Public endpoint - no authentication required
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (err) {
    res.status(500).json({ status: 'error', message: 'Health check failed' });
  }
});

/**
 * Get users endpoint
 * SECURITY: This endpoint should have authentication in production
 * SECURITY: Sensitive fields (email) are filtered out
 * SECURITY: Query parameters are validated
 */
app.get('/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  handleValidationErrors,
  (req, res) => {
    try {
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;

      // Mock data (in production, fetch from database with query validation)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter sensitive data (don't expose emails unless authenticated)
      // In production, check user permissions here
      const isAuthenticated = req.headers.authorization !== undefined;
      const filteredUsers = users.map(user => {
        if (isAuthenticated) {
          return user; // Return full data if authenticated
        }
        // Return only non-sensitive fields for unauthenticated users
        const { email, ...publicData } = user;
        return publicData;
      });

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: filteredUsers.length
        }
      });
    } catch (err) {
      console.error('Error fetching users:', err);
      res.status(500).json({
        status: 'error',
        message: 'Failed to fetch users'
      });
    }
  }
);

/**
 * Example POST endpoint with validation
 * SECURITY: Input validation using express-validator
 * SECURITY: Sanitized and validated inputs
 */
app.post('/users',
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .escape(), // Sanitize HTML
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail(), // Normalize email format
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // In production: validate email uniqueness, hash password, etc.
      // For now, just return success

      res.status(201).json({
        status: 'success',
        message: 'User created',
        data: {
          id: 3,
          name,
          email
        }
      });
    } catch (err) {
      console.error('Error creating user:', err);
      res.status(500).json({
        status: 'error',
        message: 'Failed to create user'
      });
    }
  }
);

// ============================================================================
// 404 Handler
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Not found',
    path: req.path
  });
});

// ============================================================================
// Global Error Handler
// ============================================================================

app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  // Don't expose internal error details in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(err.status || 500).json({
    status: 'error',
    message,
    // Only include error details in development
    ...(process.env.NODE_ENV === 'development' && { error: err.message })
  });
});

// ============================================================================
// Unhandled Promise Rejection Handler
// ============================================================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, send to error tracking service (e.g., Sentry)
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Gracefully shutdown in production
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// ============================================================================
// Server Startup
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

