## 1. Error Handling

### ❌ Bad: Exposing Stack Traces
```javascript
app.get('/users/:id', (req, res) => {
  const user = db.query(`SELECT * FROM users WHERE id = ${req.params.id}`);
  res.json(user);
  // If error occurs, Express returns 500 with full stack trace
});
```

### ✅ Good: Proper Error Handling
```javascript
app.get('/users/:id', async (req, res) => {
  try {
    // Validate input first
    if (!Number.isInteger(parseInt(req.params.id))) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    const user = await db.query(
      'SELECT * FROM users WHERE id = ?',
      [req.params.id]
    );

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (err) {
    console.error('Error fetching user:', err);
    // Never expose internal error details
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date(),
    error: err.message,
    path: req.path,
    method: req.method
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message
  });
});
```

---

## 2. Input Validation

### ❌ Bad: No Validation
```javascript
app.post('/users', (req, res) => {
  // Trusting all input
  const { name, email, age } = req.body;
  db.insert('users', { name, email, age });
  res.json({ success: true });
});

// Vulnerable to:
// - XSS: name = '<script>alert("xss")</script>'
// - SQL Injection: name = "'; DROP TABLE users;--"
// - Invalid data: age = "abc"
```

### ✅ Good: Comprehensive Validation
```javascript
const { body, query, param, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');

// Custom validation middleware
const validateInput = [
  body('name')
    .trim() // Remove whitespace
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters')
    .escape(), // Escape HTML entities

  body('email')
    .trim()
    .isEmail().withMessage('Valid email required')
    .normalizeEmail() // Normalize format
    .isLength({ max: 254 }).withMessage('Email too long'),

  body('age')
    .optional()
    .isInt({ min: 0, max: 150 }).withMessage('Age must be 0-150'),

  body('password')
    .isLength({ min: 8 }).withMessage('Password must be 8+ characters')
    .matches(/[A-Z]/).withMessage('Must include uppercase')
    .matches(/[0-9]/).withMessage('Must include number')
    .matches(/[!@#$%^&*]/).withMessage('Must include special char')
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'validation_error',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

app.post('/users', validateInput, handleValidationErrors, async (req, res) => {
  try {
    // Input is now validated and sanitized
    const { name, email, age, password } = req.body;

    // Check for duplicates
    const exists = await db.query('SELECT id FROM users WHERE email = ?', [email]);
    if (exists) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    // Hash password
    const hashedPassword = await hashPassword(password);

    // Insert data
    const result = await db.insert('users', {
      name,
      email,
      age,
      password: hashedPassword
    });

    res.status(201).json({
      success: true,
      userId: result.id
    });
  } catch (err) {
    console.error('Error creating user:', err);
    res.status(500).json({ error: 'Failed to create user' });
  }
});

// Validate query parameters
app.get('/users',
  query('page')
    .optional()
    .isInt({ min: 1 }).withMessage('Page must be positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).withMessage('Limit must be 1-100'),
  handleValidationErrors,
  (req, res) => {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    // Process with validated values
  }
);

// Validate URL parameters
app.get('/users/:id',
  param('id')
    .isInt().withMessage('User ID must be integer'),
  handleValidationErrors,
  (req, res) => {
    // Process with validated ID
  }
);
```

---

## 3. Authentication & Authorization

### ❌ Bad: No Authentication
```javascript
app.get('/admin/users', (req, res) => {
  // Anyone can access this
  const users = db.query('SELECT * FROM users');
  res.json(users);
});
```

### ✅ Good: JWT Authentication
```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

// Login endpoint
app.post('/login', validateInput, async (req, res) => {
  try {
    const { email, password } = req.body;

    // Find user
    const user = await db.query(
      'SELECT id, email, password_hash, role FROM users WHERE email = ?',
      [email]
    );

    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Verify password
    const validPassword = await bcrypt.compare(password, user.password_hash);
    if (!validPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Create JWT
    const token = jwt.sign(
      { userId: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET,
      { expiresIn: '24h' }
    );

    res.json({
      token,
      user: {
        id: user.id,
        email: user.email,
        role: user.role
      }
    });
  } catch (err) {
    console.error('Login error:', err);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    res.status(401).json({ error: 'Invalid token' });
  }
};

// Authorization middleware (role-based access control)
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// Protected endpoints
app.get('/profile', authenticate, (req, res) => {
  res.json({ user: req.user });
});

app.get('/admin/users', authenticate, authorize('admin'), (req, res) => {
  const users = db.query('SELECT id, email, role FROM users');
  res.json(users);
});

app.delete('/admin/users/:id', authenticate, authorize('admin'), (req, res) => {
  const userId = parseInt(req.params.id);
  db.query('DELETE FROM users WHERE id = ?', [userId]);
  res.json({ success: true });
});
```

