## 4. Data Protection

### ❌ Bad: Exposing Sensitive Data
```javascript
app.get('/users', (req, res) => {
  const users = db.query('SELECT * FROM users');
  // Returns everything including passwords, SSNs, etc.
  res.json(users);
});
```

### ✅ Good: Filtering Sensitive Data
```javascript
// Data filtering utility
const filterSensitiveFields = (user, isAdmin = false) => {
  const { password_hash, ssn, credit_card, ...publicData } = user;

  if (isAdmin) {
    return user; // Admins see everything
  }

  return publicData;
};

app.get('/users', authenticate, (req, res) => {
  const users = db.query('SELECT * FROM users');

  // Filter based on user role
  const filtered = users.map(user =>
    filterSensitiveFields(user, req.user.role === 'admin')
  );

  res.json(filtered);
});

// Specific user endpoint
app.get('/users/:id', authenticate, async (req, res) => {
  const userId = parseInt(req.params.id);

  // Users can only see their own data unless admin
  if (req.user.userId !== userId && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const user = await db.query('SELECT * FROM users WHERE id = ?', [userId]);
  const filtered = filterSensitiveFields(user, req.user.role === 'admin');

  res.json(filtered);
});
```

### ✅ Good: Password Security
```javascript
const bcrypt = require('bcrypt');

// Hashing password on registration
const hashedPassword = await bcrypt.hash(password, 10);
await db.insert('users', { email, password_hash: hashedPassword });

// Verifying password on login
const isValid = await bcrypt.compare(inputPassword, user.password_hash);

// Never store plain passwords
app.post('/register', async (req, res) => {
  try {
    const { email, password } = req.body;

    // Validate password strength
    if (password.length < 8) {
      return res.status(400).json({ error: 'Password too weak' });
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(password, 10);

    // Store hashed password
    await db.insert('users', {
      email,
      password_hash: hashedPassword
    });

    res.status(201).json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Registration failed' });
  }
});
```

