```

---

## 6. Common Vulnerabilities & Fixes

### SQL Injection

❌ **Vulnerable:**
```javascript
const userId = req.params.id;
const user = db.query(`SELECT * FROM users WHERE id = ${userId}`);
// If userId = "1; DROP TABLE users;--" DISASTER!
```

✅ **Fixed:**
```javascript
const userId = req.params.id;
const user = db.query('SELECT * FROM users WHERE id = ?', [userId]);
// Parameterized queries prevent injection
```

### Cross-Site Scripting (XSS)

❌ **Vulnerable:**
```javascript
res.send(`<h1>Hello ${req.query.name}</h1>`);
// If name = '<script>alert("xss")</script>'
```

✅ **Fixed:**
```javascript
const { escape } = require('express-validator');
const name = escape(req.query.name);
res.send(`<h1>Hello ${name}</h1>`);
// Or use template engines with auto-escaping
```

### Command Injection

❌ **Vulnerable:**
```javascript
const { exec } = require('child_process');
exec(`curl ${userProvidedUrl}`, (err, stdout) => { /* ... */ });
// If userProvidedUrl = "http://test.com; rm -rf /"
```

✅ **Fixed:**
```javascript
const { execFile } = require('child_process');
const url = require('url');

const parsedUrl = url.parse(userProvidedUrl);
execFile('curl', [userProvidedUrl], { timeout: 5000 }, (err, stdout) => {
  // Use whitelist/validation
});
```

### Path Traversal

❌ **Vulnerable:**
```javascript
app.get('/files/:filename', (req, res) => {
  res.download(`./uploads/${req.params.filename}`);
  // If filename = "../../../etc/passwd"
});
```

✅ **Fixed:**
```javascript
const path = require('path');

app.get('/files/:filename', (req, res) => {
  const filename = path.basename(req.params.filename); // Only filename, no paths
  const filepath = path.join(__dirname, 'uploads', filename);

  // Verify file is in uploads directory
  if (!filepath.startsWith(path.join(__dirname, 'uploads'))) {
    return res.status(403).json({ error: 'Access denied' });
  }

  res.download(filepath);
});
```

### Broken Authentication

❌ **Vulnerable:**
```javascript
const password = req.body.password;
if (password === user.password) { // Comparing in plain text!
  // Login successful
}
```

✅ **Fixed:**
```javascript
const bcrypt = require('bcrypt');

const isValid = await bcrypt.compare(req.body.password, user.password_hash);
if (isValid) {
  // Login successful
}
```

---

## Summary Checklist

- [ ] All errors caught and logged, never exposed
- [ ] All user input validated and sanitized
- [ ] Sensitive data filtered from responses
- [ ] Authentication required for protected endpoints
- [ ] Authorization checked for role-based access
- [ ] Passwords hashed with bcrypt
- [ ] Database queries use parameterized statements
- [ ] Logging includes who did what and when
- [ ] No sensitive data logged
- [ ] Security headers configured
- [ ] CORS properly configured
- [ ] Rate limiting implemented
- [ ] Request size limits configured

