      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      timestamp: new Date().toISOString()
    });
  });
  next();
});

// ============ ROUTES ============

/**
 * Health check endpoint
 * @route GET /health
 * @returns {Object} Status and timestamp
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      requestId: req.id
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint with pagination
 * @route GET /users
 * @query {number} limit - Number of users to return (1-100, default: 10)
 * @query {number} offset - Number of users to skip (default: 0)
 * @returns {Object} Array of users with pagination info
 */
app.get('/users',
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Invalid input parameters',
          requestId: req.id,
          details: errors.array()
        });
      }

      // Parse and sanitize inputs
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Mock user data (in production, fetch from database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = allUsers.slice(offset, offset + limit);

      res.status(200).json({
        success: true,
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length
        },
        requestId: req.id
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============ 404 HANDLER ============

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    requestId: req.id
  });
});

// ============ ERROR HANDLING MIDDLEWARE ============

/**
 * Global error handler
 * Catches all errors and returns appropriate response
 */
app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  // Log error details
  console.error({
    requestId: req.id,
    error: err.message,
    status,
    stack: isDevelopment ? err.stack : undefined,
    timestamp: new Date().toISOString()
  });

  // Prepare error response
  const errorResponse = {
    error: isDevelopment ? err.message : 'Internal Server Error',
    requestId: req.id
  };

  // Include stack trace only in development
  if (isDevelopment && err.stack) {
    errorResponse.stack = err.stack;
  }

  res.status(status).json(errorResponse);
});

