// Improved Express application with security best practices
// This version includes error handling, input validation, and security headers

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers (Helmet.js)
app.use(helmet());

// 2. Request Logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 3. CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 3600
};
app.use(cors(corsOptions));

// 4. Body Parser with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));

// 5. Rate Limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks
    return req.path === '/health';
  }
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 20, // stricter limit
  message: 'Too many sensitive requests from this IP'
});

app.use(generalLimiter);

// ============================================================================
// VALIDATION RULES
// ============================================================================

// Reusable validation rules
const validatePagination = [
  query('page')
    .optional()
    .isInt({ min: 1, max: 10000 })
    .toInt()
    .withMessage('Page must be a positive integer (max 10000)'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
];

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health Check Endpoint
 * GET /health
 * No rate limiting applied (excluded in generalLimiter)
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Get Users Endpoint
 * GET /users
 * 
 * SECURITY IMPROVEMENTS:
 * - Input validation for pagination parameters
 * - Rate limiting applied
 * - Sensitive data protection (emails removed)
 * - Error handling
 * - Response validation
 */
app.get('/users', strictLimiter, validatePagination, (req, res, next) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array().map(err => ({
          field: err.param,
          message: err.msg
        }))
      });
    }

    // Pagination parameters with defaults
    const page = req.query.page || 1;
    const limit = Math.min(req.query.limit || 10, 100); // Cap at 100
    const offset = (page - 1) * limit;

    // Mock user data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
      { id: 3, name: 'Charlie' },
      { id: 4, name: 'Diana' },
      { id: 5, name: 'Eve' },
    ];

    // SECURITY: Don't expose email addresses
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Return paginated response with metadata
    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limit)
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

/**
 * Create User Endpoint (Example)
 * POST /users
 * 
 * Demonstrates input validation
 */
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters')
    .escape(), // Prevent XSS
  body('email')
    .trim()
    .isEmail().withMessage('Valid email is required')
    .normalizeEmail(),
], (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array().map(err => ({
          field: err.param,
          message: err.msg
        }))
      });
    }

    // In production, validate against database constraints
    // and use parameterized queries to prevent SQL injection

    res.status(201).json({
      id: Date.now(), // Mock ID
      name: req.body.name,
      email: req.body.email // Don't echo back unvalidated input
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// 404 ERROR HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Global error handler
 * Must be defined last, after all other app.use() and routes
 */
app.use((err, req, res, next) => {
  // Log error details for debugging (don't expose in response)
  console.error({
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    error: err.message,
    stack: err.stack,
    ip: req.ip
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Build safe error response
  const response = {
    error: 'Internal Server Error',
    timestamp: new Date().toISOString()
  };

  // In development, include error details
  if (process.env.NODE_ENV !== 'production') {
    response.message = err.message;
    response.stack = err.stack;
  }

  // In production, be generic
  if (process.env.NODE_ENV === 'production') {
    // Log to external service (e.g., Sentry, DataDog)
    // externalLogger.error(err, { req, statusCode });
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  console.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

// Start server
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} (${process.env.NODE_ENV || 'development'})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Implementation Guide: Security Improvements for app.js

## Quick Start

### 1. Install Dependencies
```bash
npm install express helmet cors express-rate-limit express-validator morgan dotenv
npm install --save-dev nodemon eslint snyk
```

### 2. Setup Environment File
```bash
cp .env.example .env
# Edit .env with your configuration
```

### 3. Run the Improved Application
```bash
# Development
npm run dev

# Production
npm start
```

---

## Detailed Security Improvements

### 1. Security Headers (Helmet.js)
**What it does:** Adds HTTP response headers to protect against common attacks.

```javascript
app.use(helmet());
```

**Headers Added:**
- `Content-Security-Policy` - Prevents XSS attacks
- `X-Frame-Options` - Prevents clickjacking
- `X-Content-Type-Options` - Prevents MIME type sniffing
- `Strict-Transport-Security` - Enforces HTTPS
- `X-XSS-Protection` - Legacy XSS protection

**Customization Example:**
```javascript
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "trusted-cdn.com"],
      styleSrc: ["'self'", "'unsafe-inline'"]
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));
```

### 2. CORS (Cross-Origin Resource Sharing)
**What it does:** Controls which origins can access your API.

```javascript
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));
```

**Security Considerations:**
- Never use `origin: '*'` with `credentials: true`
- Whitelist specific origins
- Use environment variables for configuration
- Restrict HTTP methods to only what's needed

### 3. Rate Limiting
**What it does:** Prevents brute force attacks and DoS.

```javascript
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests...',
  standardHeaders: true,
  legacyHeaders: false
});

app.use(generalLimiter);
```

**Advanced: Different Limits for Different Routes**
```javascript
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20 // stricter for sensitive endpoints
});

app.post('/users', strictLimiter, (req, res) => { /* ... */ });
```

**For Production with Redis:**
```javascript
const RedisStore = require('rate-limit-redis');
const redis = require('redis');
const client = redis.createClient();

const limiter = rateLimit({
  store: new RedisStore({
    client: client,
    prefix: 'rl:' // rate limit prefix
  }),
  windowMs: 15 * 60 * 1000,
  max: 100
});
```

### 4. Input Validation with express-validator

**Basic Validation:**
```javascript
app.post('/users', [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters')
    .escape(), // Prevent XSS
  body('email')
    .trim()
    .isEmail().withMessage('Valid email is required')
    .normalizeEmail()
], (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process validated data
});
```

**Common Validation Rules:**
- `.notEmpty()` - Field is required
- `.isEmail()` - Valid email format
- `.isLength()` - String length constraints
- `.isInt()`, `.isFloat()` - Numeric validation
- `.matches()` - Regex pattern matching
- `.escape()` - HTML escape (XSS prevention)
- `.trim()` - Whitespace removal
- `.normalizeEmail()` - Email normalization

### 5. Error Handling

**Global Error Handler:**
```javascript
app.use((err, req, res, next) => {
  console.error(err.stack);

  const statusCode = err.statusCode || 500;

  const response = {
    error: 'Internal Server Error',
    timestamp: new Date().toISOString()
  };

  // Dev vs Production
  if (process.env.NODE_ENV !== 'production') {
    response.message = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});
```

**Custom Error Class:**
```javascript
class ApiError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
  }
}

// Usage
app.get('/users/:id', (req, res, next) => {
  if (!isValidId(req.params.id)) {
    return next(new ApiError('Invalid user ID', 400));
  }
  // Continue processing
});
```

### 6. Request Logging with Morgan

**Basic Setup:**
```javascript
app.use(morgan('combined')); // Detailed logs
// or
app.use(morgan('dev')); // Development format
```

**Custom Format:**
```javascript
morgan.token('user', (req) => req.user?.id || 'anonymous');

app.use(morgan(':remote-addr - :user [:date[clf]] ":method :url" :status :res[content-length]'));
```

### 7. Sensitive Data Protection

**What NOT to do:**
```javascript
// ❌ DON'T expose emails, phone numbers, passwords
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com', phone: '555-1234' }
  ]);
});
```

**What to do:**
```javascript
// ✅ DO only expose necessary data
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' }
  ]);
});

// Use separate authenticated endpoint for detailed info
app.get('/users/:id/profile', authenticate, (req, res) => {
  // Only return data for current user or admin
});
```

### 8. SQL Injection Prevention

**Using Parameterized Queries:**
```javascript
// ❌ DON'T concatenate user input
const query = `SELECT * FROM users WHERE id = ${userId}`;

// ✅ DO use parameterized queries
const query = 'SELECT * FROM users WHERE id = $1';
db.query(query, [userId]);
```

### 9. Environment Variables

**Never hardcode secrets:**
```javascript
// ❌ DON'T
const API_KEY = 'super-secret-key-12345';
const DB_PASSWORD = 'mypassword';

// ✅ DO
require('dotenv').config();
const API_KEY = process.env.API_KEY;
const DB_PASSWORD = process.env.DB_PASSWORD;

if (!API_KEY) {
  throw new Error('API_KEY environment variable is required');
}
```

