# Quick Reference: Security Best Practices

## 🛡️ Security Checklist for Express Applications

### Input Validation ✅
```javascript
// ✅ DO: Validate and sanitize all inputs
const { body, query, validationResult } = require('express-validator');

app.post('/users', [
  body('email').isEmail().normalizeEmail(),
  body('name').trim().isLength({ min: 2, max: 100 }),
  body('age').optional().isInt({ min: 18, max: 120 }),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process valid data
});

// ❌ DON'T: Use input directly without validation
app.post('/users', (req, res) => {
  const user = req.body; // DANGEROUS!
  db.insert(user);
});
```

### Error Handling ✅
```javascript
// ✅ DO: Use try-catch and error middleware
app.get('/users/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id);
    if (!Number.isInteger(id)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }
    const user = db.getUser(id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Server error' });
  }
});

// ❌ DON'T: Let errors crash the application
app.get('/users/:id', (req, res) => {
  const user = db.getUser(req.params.id); // May throw
  res.json(user);
});
```

### Rate Limiting ✅
```javascript
// ✅ DO: Limit requests to prevent abuse
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

const loginLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 5
});

app.use(limiter); // Apply to all routes
app.post('/login', loginLimiter, (req, res) => {
  // Login with stricter limiting
});

// ❌ DON'T: Allow unlimited requests
app.post('/login', (req, res) => {
  // Vulnerable to brute force!
});
```

### Security Headers ✅
```javascript
// ✅ DO: Use Helmet to set security headers
const helmet = require('helmet');
app.use(helmet());

// This sets:
// - X-Content-Type-Options: nosniff
// - X-Frame-Options: DENY
// - X-XSS-Protection: 1; mode=block
// - Strict-Transport-Security
// - Content-Security-Policy
// ... and more!

// ❌ DON'T: Skip security headers
app.use(express.json()); // Missing helmet!
```

### CORS Configuration ✅
```javascript
// ✅ DO: Configure CORS with specific origins
const cors = require('cors');

const corsOptions = {
  origin: ['https://example.com', 'https://app.example.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));

// ❌ DON'T: Allow all origins
app.use(cors()); // Allows ANY origin to access your API!
```

### Data Minimization ✅
```javascript
// ✅ DO: Return only necessary fields
app.get('/users/:id', (req, res) => {
  const user = db.getUser(req.params.id);
  res.json({
    id: user.id,
    name: user.name,
    // Don't include: password_hash, ssn, etc.
  });
});

// ❌ DON'T: Expose all fields
app.get('/users/:id', (req, res) => {
  const user = db.getUser(req.params.id);
  res.json(user); // Includes password_hash, internal IDs, etc!
});
```

### Authentication ✅
```javascript
// ✅ DO: Verify user identity
const jwt = require('jsonwebtoken');

const verifyToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  jwt.verify(token, process.env.SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/users', verifyToken, (req, res) => {
  // Only authenticated users can access
  res.json(users);
});

// ❌ DON'T: Skip authentication
app.get('/users', (req, res) => {
  // Anyone can access!
  res.json(users);
});
```

### Request Size Limits ✅
```javascript
// ✅ DO: Limit payload size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ❌ DON'T: Allow unlimited file sizes
app.use(express.json()); // No size limit!
```

### Logging ✅
```javascript
// ✅ DO: Log important security events
const morgan = require('morgan');
app.use(morgan('combined'));

// Also log authentication events
console.log(`Login attempt: ${email} from ${ip}`);
console.log(`Failed login: ${email} - ${reason}`);
console.log(`Suspicious activity: ${description}`);

// ❌ DON'T: Skip logging
// No way to investigate security incidents!
```

### Environment Configuration ✅
```javascript
// ✅ DO: Use environment variables for secrets
require('dotenv').config();

const dbPassword = process.env.DB_PASSWORD;
const apiKey = process.env.API_KEY;
const jwtSecret = process.env.JWT_SECRET;

// ❌ DON'T: Hard-code secrets
const dbPassword = 'admin123'; // EXPOSED!
const apiKey = 'sk-1234567890'; // In version control!
```

---

## 🚨 Common Vulnerabilities to Avoid

### SQL Injection
```javascript
// ❌ VULNERABLE
const query = `SELECT * FROM users WHERE email = '${email}'`;

// ✅ SAFE
const query = 'SELECT * FROM users WHERE email = ?';
db.query(query, [email]);
```

### XSS (Cross-Site Scripting)
```javascript
// ❌ VULNERABLE
res.send(`<h1>Hello ${name}</h1>`); // If name = <script>alert('xss')</script>

// ✅ SAFE
res.json({ message: `Hello ${name}` }); // JSON prevents script execution
// OR
const DOMPurify = require('isomorphic-dompurify');
res.send(`<h1>Hello ${DOMPurify.sanitize(name)}</h1>`);
```

### CSRF (Cross-Site Request Forgery)
```javascript
// ✅ SAFE: Use csrf middleware
const csrf = require('csurf');
app.use(csrf());

app.post('/action', (req, res) => {
  if (!req.csrfToken()) {
    return res.status(403).json({ error: 'CSRF token missing' });
  }
  // Process request
});
```

### Insecure Deserialization
```javascript
// ❌ VULNERABLE
app.post('/data', (req, res) => {
  const data = eval(req.body.data); // DANGEROUS!
});

// ✅ SAFE
app.post('/data', (req, res) => {
  const data = JSON.parse(req.body.data); // JSON only
});
```

---

## 🔧 Express Security Middleware Stack

```javascript
// RECOMMENDED SECURITY STACK
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// 1. Security headers
app.use(helmet());

// 2. Logging
app.use(morgan('combined'));

// 3. Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
}));

// 4. CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',')
}));

// 5. Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 6. Routes with validation
app.post('/users', [
  body('email').isEmail(),
  body('name').trim().isLength({ min: 2 })
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Handle request
});

// 7. 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// 8. Error handler
app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

app.listen(3000);
```

---

## 📋 Pre-Deployment Security Checklist

- [ ] Input validation on all endpoints
- [ ] Error handling with secure messages
- [ ] Rate limiting implemented
- [ ] Security headers via Helmet
- [ ] CORS properly configured
- [ ] Request size limits set
- [ ] Logging implemented
- [ ] Environment variables used for secrets
- [ ] Authentication/Authorization working
- [ ] No stack traces in production responses
- [ ] No sensitive data in logs
- [ ] HTTPS/TLS configured
- [ ] Database prepared statements used
- [ ] No hard-coded credentials
- [ ] Security headers tested
- [ ] Rate limiting tested
- [ ] Input validation tested
- [ ] Error handling tested

---

## 🔗 External Resources

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Handbook](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/security/)
- [Helmet.js](https://helmetjs.github.io/)
- [OWASP Cheat Sheets](https://cheatsheetseries.owasp.org/)

---

## 🎯 Key Principles

1. **Never trust user input** - Always validate and sanitize
2. **Fail securely** - Errors shouldn't expose sensitive information
3. **Defense in depth** - Multiple layers of security
4. **Principle of least privilege** - Only give necessary access
5. **Default deny** - Restrict by default, open only what's needed
6. **Secure by default** - Security built into design, not added later
7. **Keep dependencies updated** - Regular security patches
8. **Log security events** - Audit trail for investigation

---

