// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const cors = require('cors');
const morgan = require('morgan');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers - Helmet protects against common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// 2. CORS Configuration - Restrict cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// 3. Rate Limiting - Prevent brute force and DoS attacks
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  message: 'Too many attempts, please try again later.',
});

app.use(generalLimiter);

// 4. Request Logging - Morgan for HTTP request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Body Parser Configuration with Size Limits
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// MIDDLEWARE FOR SANITIZATION
// ============================================================================

// Middleware to sanitize and validate request
const sanitizeQuery = (req, res, next) => {
  try {
    // Sanitize query parameters
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        req.query[key] = validator.trim(req.query[key]);
        req.query[key] = validator.escape(req.query[key]);
      }
    }
    next();
  } catch (error) {
    res.status(400).json({ error: 'Invalid query parameters' });
  }
};

// ============================================================================
// ERROR HANDLING UTILITIES
// ============================================================================

class APIError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

// ============================================================================
// ROUTES
// ============================================================================

// Health Check Endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Get Users Endpoint with Input Validation
app.get('/users', sanitizeQuery, (req, res, next) => {
  try {
    // Input validation: Check page and limit parameters
    let page = req.query.page ? parseInt(req.query.page, 10) : 1;
    let limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;

    // Validate pagination parameters
    if (!Number.isInteger(page) || page < 1) {
      throw new APIError('Page must be a positive integer', 400);
    }
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new APIError('Limit must be between 1 and 100', 400);
    }

    // User data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const users = allUsers.slice(startIndex, startIndex + limit);

    // Validate we have users to return
    if (users.length === 0) {
      throw new APIError('No users found', 404);
    }

    res.json({
      success: true,
      data: users,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        pages: Math.ceil(allUsers.length / limit),
      },
    });
  } catch (error) {
    next(error);
  }
});

// Get User by ID Endpoint
app.get('/users/:id', sanitizeQuery, (req, res, next) => {
  try {
    const { id } = req.params;

    // Validate ID is a valid positive integer
    if (!Number.isInteger(parseInt(id, 10)) || parseInt(id, 10) < 1) {
      throw new APIError('Invalid user ID', 400);
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find((u) => u.id === parseInt(id, 10));

    if (!user) {
      throw new APIError('User not found', 404);
    }

    res.json({
      success: true,
      data: user,
    });
  } catch (error) {
    next(error);
  }
});

// Create User Endpoint (with validation)
app.post('/users', strictLimiter, (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string') {
      throw new APIError('Name is required and must be a string', 400);
    }
    if (!email || !validator.isEmail(email)) {
      throw new APIError('Valid email is required', 400);
    }

    // Sanitize inputs
    const sanitizedName = validator.trim(validator.escape(name));
    const sanitizedEmail = validator.normalizeEmail(email);

    // Validate length constraints
    if (sanitizedName.length < 2 || sanitizedName.length > 100) {
      throw new APIError('Name must be between 2 and 100 characters', 400);
    }

    // In production, save to database and check for duplicates
    const newUser = {
      id: Math.random(), // Use UUID in production
      name: sanitizedName,
      email: sanitizedEmail,
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// 404 and ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Resource not found',
    path: req.originalUrl,
  });
});

// Global Error Handler Middleware
app.use((err, req, res, next) => {
  // Log error
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.originalUrl,
    error: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Handle known errors
  if (err instanceof APIError) {
    return res.status(err.statusCode).json({
      success: false,
      error: err.message,
    });
  }

  // Handle validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      success: false,
      error: 'Validation error',
      details: err.message,
    });
  }

  // Generic error (don't leak sensitive info in production)
  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    success: false,
    error: message,
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (${NODE_ENV})`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

# Security Review and Improvement Guide

## Executive Summary
The original app.js is a basic Express application that lacks critical security measures. This document outlines all issues and improvements implemented.

---

## 🔴 CRITICAL ISSUES FOUND

### 1. **Missing Error Handling**
**Issue:** No try-catch blocks or error middleware
```javascript
// ❌ Original - Unhandled errors will crash the app
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Fix:** Implemented comprehensive error handling
```javascript
// ✅ Improved - All errors caught and handled gracefully
app.get('/users', sanitizeQuery, (req, res, next) => {
  try {
    // ... logic
  } catch (error) {
    next(error); // Pass to error middleware
  }
});

// Global error handler
app.use((err, req, res, next) => {
  // ... centralized error handling
});
```

---

### 2. **No Input Validation**
**Issue:** Query parameters and request bodies are used without validation
```javascript
// ❌ Vulnerable to various attacks
app.get('/users', (req, res) => {
  res.json([...]); // No validation of req.query or req.params
});
```

**Fixes Implemented:**
- Type checking for all inputs
- Length constraints validation
- Email format validation using validator library
- Integer validation for IDs and pagination
- Range checking for pagination limits (max 100)

```javascript
// ✅ Comprehensive validation
if (!Number.isInteger(page) || page < 1) {
  throw new APIError('Page must be a positive integer', 400);
}
if (!validator.isEmail(email)) {
  throw new APIError('Valid email is required', 400);
}
```

---

### 3. **Missing Security Headers**
**Issue:** Application vulnerable to XSS, clickjacking, and other header-based attacks
```javascript
// ❌ No security headers
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Fix:** Implemented Helmet.js
```javascript
// ✅ Added comprehensive security headers
app.use(helmet({
  contentSecurityPolicy: {...},
  hsts: {...},
  frameguard: {...},
  xssFilter: {...}
}));
```

**Headers Added:**
- `Content-Security-Policy` - Prevents XSS attacks
- `Strict-Transport-Security` - Enforces HTTPS
- `X-Frame-Options` - Prevents clickjacking
- `X-Content-Type-Options` - Prevents MIME type sniffing
- `X-XSS-Protection` - XSS protection

---

### 4. **No Rate Limiting**
**Issue:** Application vulnerable to brute force, DoS, and spam attacks
```javascript
// ❌ Unlimited requests allowed
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Fix:** Implemented express-rate-limit
```javascript
// ✅ Rate limiting configured
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter for sensitive operations
});

app.use(generalLimiter);
app.post('/users', strictLimiter, ...);
```

---

### 5. **Exposed Sensitive Data**
**Issue:** Full user email addresses returned without access control
```javascript
// ❌ Potentially sensitive data exposed
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ]);
});
```

**Fix:** 
- Added proper HTTP status codes (201 for creation, 404 for not found)
- Added success flags and structured responses
- Implemented pagination to limit data exposure
- Ready for authentication/authorization layer

```javascript
// ✅ Structured response with pagination
res.json({
  success: true,
  data: users,
  pagination: {
    page, limit, total, pages
  }
});
```

---

### 6. **No Request Logging**
**Issue:** Difficult to audit and debug security issues
```javascript
// ❌ No logging mechanism
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Fix:** Implemented Morgan middleware
```javascript
// ✅ Comprehensive request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// Error logging in global handler
console.error({
  timestamp: new Date().toISOString(),
  method: req.method,
  url: req.originalUrl,
  error: err.message,
  stack: NODE_ENV === 'development' ? err.stack : undefined,
});
```

---

### 7. **No HTTPS Enforcement**
**Issue:** Communication can be intercepted
```javascript
// ❌ HTTP only, no encryption
app.listen(3000);
```

**Fix:** Implemented HSTS (HTTP Strict Transport Security)
```javascript
// ✅ HSTS configured via Helmet
app.use(helmet({
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));
```

---

### 8. **Missing CORS Configuration**
**Issue:** Vulnerable to cross-origin attacks or overly permissive
```javascript
// ❌ No CORS configuration
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Fix:** Implemented CORS with whitelist
```javascript
// ✅ Restricted CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));
```

---

### 9. **Hardcoded Configuration**
**Issue:** Secrets and settings hardcoded, not environment-specific
```javascript
// ❌ Hardcoded values
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Fix:** Environment variables via .env
```javascript
// ✅ Environment-driven configuration
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS;
```

---

### 10. **No Request Size Limits**
**Issue:** Vulnerable to buffer overflow attacks
```javascript
// ❌ No size limits on request bodies
app.use(express.json());
```

**Fix:** Added payload size limits
```javascript
// ✅ Size limits configured
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 11. **Unhandled 404s**
**Issue:** No proper 404 handling
```javascript
// ❌ Missing routes return default Express response
```

**Fix:** Explicit 404 handler
```javascript
// ✅ Proper 404 response
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Resource not found',
    path: req.originalUrl,
  });
});
```

---

### 12. **No Graceful Shutdown**
**Issue:** Server terminates abruptly, may corrupt data
```javascript
// ❌ No cleanup on shutdown
app.listen(3000);
```

**Fix:** Graceful shutdown handlers
```javascript
// ✅ Graceful shutdown implemented
process.on('SIGTERM', () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    process.exit(0);
  });
});
```

---

## ✅ IMPROVEMENTS IMPLEMENTED

### Security Enhancements
- [x] Helmet.js for security headers
- [x] CORS with whitelist
- [x] Rate limiting (general and strict)
- [x] Request size limits
- [x] Input validation and sanitization
- [x] Error handling middleware
- [x] HSTS enforcement
- [x] Request logging

### Code Quality
- [x] Custom APIError class
- [x] Structured error responses
- [x] Consistent response format
- [x] Environment configuration
- [x] Graceful shutdown
